INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (76, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Authored and organized the "New York Legislators Stand with Israel" solidarity letter. Serves as President of the NY Chapter of the National Association of Jewish Legislators and is described as "a staunch voice for the Jewish community and for the state of Israel."', 'Authored the October 20, 2023 "New York Legislators Stand With Israel" letter signed by dozens of legislators. Serves as President of the NY Chapter of the National Association of Jewish Legislators. Long-standing pro-Israel voice in the Assembly. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://spectrumlocalnews.com/nys/central-ny/politics/2023/10/30/new-york-lawmakers-sign-onto-letter-supporting-israel') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Authored and organized the "New York Legislators Stand with Israel" solidarity letter. Serves as President of the NY Chapter of the National Association of Jewish Legislators and is described as "a staunch voice for the Jewish community and for the state of Israel."', summary = 'Authored the October 20, 2023 "New York Legislators Stand With Israel" letter signed by dozens of legislators. Serves as President of the NY Chapter of the National Association of Jewish Legislators. Long-standing pro-Israel voice in the Assembly. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://spectrumlocalnews.com/nys/central-ny/politics/2023/10/30/new-york-lawmakers-sign-onto-letter-supporting-israel', updated_at = NOW();
