INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (78, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Signed the Israel solidarity letter, introduced the United Against Hate Act to combat antisemitism, hosted the Israeli Consul General at the State Capitol, and has been vocally critical of anti-Israel protests and the BDS movement.', 'Signed the October 20, 2023 solidarity letter. Introduced the United Against Hate Act. Welcomed Israeli Consul General Ofir Akunis to the NY State Capitol. Criticized antisemitic rhetoric at pro-Palestine protests. Jewish member of the Jewish Legislators Caucus. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://www.foxnews.com/opinion/stop-talking-start-teaching-new-york-must-fight-end-antisemitism-our-schools') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Signed the Israel solidarity letter, introduced the United Against Hate Act to combat antisemitism, hosted the Israeli Consul General at the State Capitol, and has been vocally critical of anti-Israel protests and the BDS movement.', summary = 'Signed the October 20, 2023 solidarity letter. Introduced the United Against Hate Act. Welcomed Israeli Consul General Ofir Akunis to the NY State Capitol. Criticized antisemitic rhetoric at pro-Palestine protests. Jewish member of the Jewish Legislators Caucus. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://www.foxnews.com/opinion/stop-talking-start-teaching-new-york-must-fight-end-antisemitism-our-schools', updated_at = NOW();
