INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (79, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Former IDF soldier (served as staff sergeant in military police), raised in Israel, grandchild of Holocaust survivors. Ran explicitly on combating antisemitism and supporting Israel. Proposed mask ban targeting anti-Israel protest tactics.', 'Born in the US, raised in Israel, drafted into the IDF at age 17. Stated: "I saw what happened in Israel. I''ll do whatever I can to prevent that from happening here." Proposed statewide mask ban aimed at preventing anonymity during anti-Israel demonstrations. First Republican to win the 16th District seat in 50 years, running on anti-antisemitism platform. Not seeking reelection. Sources: https://www.algemeiner.com/2024/11/11/ex-idf-soldier-becomes-first-republican-50-years-win-new-york-state-as') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Former IDF soldier (served as staff sergeant in military police), raised in Israel, grandchild of Holocaust survivors. Ran explicitly on combating antisemitism and supporting Israel. Proposed mask ban targeting anti-Israel protest tactics.', summary = 'Born in the US, raised in Israel, drafted into the IDF at age 17. Stated: "I saw what happened in Israel. I''ll do whatever I can to prevent that from happening here." Proposed statewide mask ban aimed at preventing anonymity during anti-Israel demonstrations. First Republican to win the 16th District seat in 50 years, running on anti-antisemitism platform. Not seeking reelection. Sources: https://www.algemeiner.com/2024/11/11/ex-idf-soldier-becomes-first-republican-50-years-win-new-york-state-as', updated_at = NOW();
