INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (86, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Self-described "proud Zionist" who signed the solidarity letter, participated in a state visit to Israel, visited a kibbutz near the Gaza border, and has chanted "Am Yisrael Chai" in response to pro-Palestinian protesters.', 'Signed the October 20, 2023 solidarity letter. Stated "I have loved Israel since my first trip in 1981." Participated in a state visit to Israel in early 2023, visiting Kibbutz Kfar Aziz near the Gaza border. Described as "a proud Zionist." Chanted "Am Yisrael Chai" at a SUNY event countering pro-Palestinian protesters. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://www.nyassembly.gov/mem/Stacey-Pheffer-Amato/story/108989') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Self-described "proud Zionist" who signed the solidarity letter, participated in a state visit to Israel, visited a kibbutz near the Gaza border, and has chanted "Am Yisrael Chai" in response to pro-Palestinian protesters.', summary = 'Signed the October 20, 2023 solidarity letter. Stated "I have loved Israel since my first trip in 1981." Participated in a state visit to Israel in early 2023, visiting Kibbutz Kfar Aziz near the Gaza border. Described as "a proud Zionist." Chanted "Am Yisrael Chai" at a SUNY event countering pro-Palestinian protesters. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://www.nyassembly.gov/mem/Stacey-Pheffer-Amato/story/108989', updated_at = NOW();
