INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (87, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Orthodox Jewish assemblyman, Co-President of the National Association of Jewish Legislators. Signed the solidarity letter, supported Gov. Cuomo''s anti-BDS executive order, and sent letters threatening action against BDS activity at SUNY campuses.', 'Signed the October 20, 2023 solidarity letter. Co-President of the National Association of Jewish Legislators (since 2017). Supported Cuomo''s executive order divesting public funds from BDS-supporting entities, stating "The BDS movement seeks to de-legitimize Israel." Co-authored letter with Lavine threatening SUNY Binghamton Student Association over BDS activity. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://en.wikipedia.org/wiki/David_W') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Orthodox Jewish assemblyman, Co-President of the National Association of Jewish Legislators. Signed the solidarity letter, supported Gov. Cuomo''s anti-BDS executive order, and sent letters threatening action against BDS activity at SUNY campuses.', summary = 'Signed the October 20, 2023 solidarity letter. Co-President of the National Association of Jewish Legislators (since 2017). Supported Cuomo''s executive order divesting public funds from BDS-supporting entities, stating "The BDS movement seeks to de-legitimize Israel." Co-authored letter with Lavine threatening SUNY Binghamton Student Association over BDS activity. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://en.wikipedia.org/wiki/David_W', updated_at = NOW();
