INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (88, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Israeli-born (first Israeli-born member of the NY State Legislature), has strongly condemned Hamas as a "radical genocidal death cult," spoken against the BDS movement, sponsored pro-Israel resolutions, and marked the anniversary of Oct 7 with commemorative statements.', 'First Israeli-born member of the NY State Legislature. Called Hamas a "radical genocidal death cult." Organized "New York Stands With Israel" conference in 2016 combating BDS. Stated: "as lawmakers, we have an opportunity to speak out against the BDS movement." Sponsored resolution stating "Supporting Israel''s right to exist is a fundamental American value." Spoke on privileged resolution congratulating Israel on its 77th anniversary. Met with families of Oct 7 hostages in Dec 2023. Sources: htt') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Israeli-born (first Israeli-born member of the NY State Legislature), has strongly condemned Hamas as a "radical genocidal death cult," spoken against the BDS movement, sponsored pro-Israel resolutions, and marked the anniversary of Oct 7 with commemorative statements.', summary = 'First Israeli-born member of the NY State Legislature. Called Hamas a "radical genocidal death cult." Organized "New York Stands With Israel" conference in 2016 combating BDS. Stated: "as lawmakers, we have an opportunity to speak out against the BDS movement." Sponsored resolution stating "Supporting Israel''s right to exist is a fundamental American value." Spoke on privileged resolution congratulating Israel on its 77th anniversary. Met with families of Oct 7 hostages in Dec 2023. Sources: htt', updated_at = NOW();
