INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (89, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Signed the Israel solidarity letter and met with families of Oct 7 hostages alongside Assemblywoman Rozic. Represents Northeast Queens with a large Jewish community and advocates for pro-Israel issues.', 'Signed the October 20, 2023 solidarity letter. On December 13, 2023, joined Assemblywoman Rozic and Israel in New York to meet with families of hostages taken during the Oct 7 attack. Advocates for the large Jewish community in Northeast Queens. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Signed the Israel solidarity letter and met with families of Oct 7 hostages alongside Assemblywoman Rozic. Represents Northeast Queens with a large Jewish community and advocates for pro-Israel issues.', summary = 'Signed the October 20, 2023 solidarity letter. On December 13, 2023, joined Assemblywoman Rozic and Israel in New York to meet with families of hostages taken during the Oct 7 attack. Advocates for the large Jewish community in Northeast Queens. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', updated_at = NOW();
