INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (90, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Orthodox Jewish assemblyman, grandson of Holocaust survivors, who studied at a yeshiva in Jerusalem. Signed the solidarity letter, introduced the HOPE Act to codify the IHRA antisemitism definition in NY law, and has been a vocal defender of the Jewish community against antisemitism and anti-Israel protests.', 'Signed the October 20, 2023 solidarity letter. Introduced the HOPE Act (Honoring Our Pledge to Eliminate Antisemitism) to codify the IHRA antisemitism definition in New York State law. Studied for four years at Yeshiva Bircas HaTorah in the Old City in Jerusalem. Orthodox Jew and grandson of Holocaust survivors. Criticized planned protests targeting Jewish communities. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://qns.com/2024/12/assembly') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Orthodox Jewish assemblyman, grandson of Holocaust survivors, who studied at a yeshiva in Jerusalem. Signed the solidarity letter, introduced the HOPE Act to codify the IHRA antisemitism definition in NY law, and has been a vocal defender of the Jewish community against antisemitism and anti-Israel protests.', summary = 'Signed the October 20, 2023 solidarity letter. Introduced the HOPE Act (Honoring Our Pledge to Eliminate Antisemitism) to codify the IHRA antisemitism definition in New York State law. Studied for four years at Yeshiva Bircas HaTorah in the Old City in Jerusalem. Orthodox Jew and grandson of Holocaust survivors. Criticized planned protests targeting Jewish communities. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://qns.com/2024/12/assembly', updated_at = NOW();
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (90, 16, 'Signed the October 20, 2023 solidarity letter. Introduced the HOPE Act (Honoring Our Pledge to Eliminate Antisemitism) to codify the IHRA antisemitism definition in New York State law. Studied for fou') ON CONFLICT (person_id, criterion_id) DO NOTHING;
