INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (91, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Signed the Israel solidarity letter and has convened Jewish Leadership Breakfasts to address community concerns. Worked to secure $70 million for nonpublic school safety grants in response to post-Oct 7 antisemitism.', 'Signed the October 20, 2023 solidarity letter. Convened Jewish Leadership Breakfasts with Queens-based Jewish organizations. Worked with State Senator Gianaris to secure $70 million for Nonpublic School Safety Equipment (NPSE) grants following Oct 7 attacks. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://assembly.state.ny.us/mem/Andrew-Hevesi/story/110451') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Signed the Israel solidarity letter and has convened Jewish Leadership Breakfasts to address community concerns. Worked to secure $70 million for nonpublic school safety grants in response to post-Oct 7 antisemitism.', summary = 'Signed the October 20, 2023 solidarity letter. Convened Jewish Leadership Breakfasts with Queens-based Jewish organizations. Worked with State Senator Gianaris to secure $70 million for Nonpublic School Safety Equipment (NPSE) grants following Oct 7 attacks. Sources: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf ; https://assembly.state.ny.us/mem/Andrew-Hevesi/story/110451', updated_at = NOW();
