INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (94, (SELECT id FROM topics WHERE slug = 'israel'), 'oppose', 'inferred', 'ai', 'Called for a ceasefire in Gaza in February 2024, though with a conditional framing ("with the right controls in place"), placing him among NY elected officials publicly critical of the continuation of military operations.', 'On February 27, 2024, Anderson wrote on X: "We are approaching nearly 150 days of conflict. There has to be a pathway towards peace in this moment. The killings of innocent lives as a casualty of a never-ending war can not sustain. It is clear that a ceasefire (with the right controls in place) can achieve this peace." Listed among NY elected officials calling for ceasefire by City & State NY. Source: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-ga') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'oppose', rationale = 'Called for a ceasefire in Gaza in February 2024, though with a conditional framing ("with the right controls in place"), placing him among NY elected officials publicly critical of the continuation of military operations.', summary = 'On February 27, 2024, Anderson wrote on X: "We are approaching nearly 150 days of conflict. There has to be a pathway towards peace in this moment. The killings of innocent lives as a casualty of a never-ending war can not sustain. It is clear that a ceasefire (with the right controls in place) can achieve this peace." Listed among NY elected officials calling for ceasefire by City & State NY. Source: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-ga', updated_at = NOW();
