INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (165, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Tague praised the Trump-brokered Israel-Palestine peace deal as a "game changer" and called for the removal of assembly colleagues who voiced support for Hamas or the DSA, indicating strong pro-Israel alignment.', 'Tague praised the Trump Israel-Palestine peace deal as saving lives and offering "a brighter future for both Israelis and Palestinians" (Facebook post). He also called for the removal of DSA-aligned assembly members who he said supported Hamas after Oct 7. Source: https://www.facebook.com/chris.tague.14/photos/president-trumps-historic-israel-palestine-peace-deal-is-a-game-changer-that-bri/1206202051319187/ ; https://midhudsonnews.com/2023/10/16/assemblymembers-begin-war-on-words-over-israel/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Tague praised the Trump-brokered Israel-Palestine peace deal as a "game changer" and called for the removal of assembly colleagues who voiced support for Hamas or the DSA, indicating strong pro-Israel alignment.', summary = 'Tague praised the Trump Israel-Palestine peace deal as saving lives and offering "a brighter future for both Israelis and Palestinians" (Facebook post). He also called for the removal of DSA-aligned assembly members who he said supported Hamas after Oct 7. Source: https://www.facebook.com/chris.tague.14/photos/president-trumps-historic-israel-palestine-peace-deal-is-a-game-changer-that-bri/1206202051319187/ ; https://midhudsonnews.com/2023/10/16/assemblymembers-begin-war-on-words-over-israel/', updated_at = NOW();
