INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (166, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'DSA member who cosponsored the "Not on Our Dime" bill targeting Israeli settlement funding, called for an immediate ceasefire, criticized Governor Hochul''s pro-Israel response as "calling for more deaths and war crimes," and was one of the first to call for ceasefire in 2023.', 'Cosponsored "Not on Our Dime" bill (A6943) with Mamdani targeting nonprofit funding of Israeli settlements. Signed January 2024 JVP Action letter calling for immediate and permanent ceasefire. Tweeted "The Governor has no empathy for her Palestinian constituents. Instead, she effectively calls for more deaths and war crimes." Sources: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/ ; https://jacobin.com/2023/08/zohran-mamdani-not-on-our-d') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'DSA member who cosponsored the "Not on Our Dime" bill targeting Israeli settlement funding, called for an immediate ceasefire, criticized Governor Hochul''s pro-Israel response as "calling for more deaths and war crimes," and was one of the first to call for ceasefire in 2023.', summary = 'Cosponsored "Not on Our Dime" bill (A6943) with Mamdani targeting nonprofit funding of Israeli settlements. Signed January 2024 JVP Action letter calling for immediate and permanent ceasefire. Tweeted "The Governor has no empathy for her Palestinian constituents. Instead, she effectively calls for more deaths and war crimes." Sources: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/ ; https://jacobin.com/2023/08/zohran-mamdani-not-on-our-d', updated_at = NOW();
