INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (167, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Signed the October 2023 "New York Legislators Stand with Israel" letter, which strongly condemned the Hamas attack and pledged solidarity with Israel and the Jewish state.', 'Listed as a signatory on the October 20, 2023 "NEW YORK LEGISLATORS STAND WITH ISRAEL" letter from the NY Assembly/Senate, which called the Oct 7 attack "a war crime" and pledged to "continue to stand with Israel." Source: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Signed the October 2023 "New York Legislators Stand with Israel" letter, which strongly condemned the Hamas attack and pledged solidarity with Israel and the Jewish state.', summary = 'Listed as a signatory on the October 20, 2023 "NEW YORK LEGISLATORS STAND WITH ISRAEL" letter from the NY Assembly/Senate, which called the Oct 7 attack "a war crime" and pledged to "continue to stand with Israel." Source: https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', updated_at = NOW();
