INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (168, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Only US state legislator to attend the JNS International Policy Summit in Jerusalem (April 2025), works closely with Jewish Federation in Dutchess County, and has spoken against anti-Zionism in state politics.', 'Attended JNS International Policy Summit in Jerusalem in April 2025 as the only US state legislator present. Has visited Israel twice. Works with the Jewish Federation of Dutchess County. Stated the fight against "anti-Zionism and anti-Israel rhetoric" is ongoing. Sources: https://www.jns.org/ny-assemblyman-stands-with-jewish-community-at-jns-summit/ ; https://www.columbusjewishnews.com/jns/new-york-assemblyman-stands-with-jewish-community-at-jns-summit/article_e801a110-0947-517f-a966-4a9e0d9743') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Only US state legislator to attend the JNS International Policy Summit in Jerusalem (April 2025), works closely with Jewish Federation in Dutchess County, and has spoken against anti-Zionism in state politics.', summary = 'Attended JNS International Policy Summit in Jerusalem in April 2025 as the only US state legislator present. Has visited Israel twice. Works with the Jewish Federation of Dutchess County. Stated the fight against "anti-Zionism and anti-Israel rhetoric" is ongoing. Sources: https://www.jns.org/ny-assemblyman-stands-with-jewish-community-at-jns-summit/ ; https://www.columbusjewishnews.com/jns/new-york-assemblyman-stands-with-jewish-community-at-jns-summit/article_e801a110-0947-517f-a966-4a9e0d9743', updated_at = NOW();
