INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (215, (SELECT id FROM topics WHERE slug = 'israel'), 'oppose', 'inferred', 'ai', 'Epstein signed an open letter from Jewish elected officials in February 2024 that condemned Hamas but also stated they "cannot support the actions of the current Israeli government," criticized mass destruction in Gaza, and called for a two-state solution and halt to civilian killings.', 'Signed "An Open Letter From Jewish Elected Officials Regarding The War In Gaza" (Feb 2024) with Krueger, Hoylman-Sigal, Lander, and Restler. The letter condemned Hamas, criticized Netanyahu government for civilian deaths and settlement policy, called for hostage negotiations and a two-state solution. Source: https://www.nysenate.gov/newsroom/articles/2024/liz-krueger/open-letter-jewish-elected-officials-regarding-war-gaza') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'oppose', rationale = 'Epstein signed an open letter from Jewish elected officials in February 2024 that condemned Hamas but also stated they "cannot support the actions of the current Israeli government," criticized mass destruction in Gaza, and called for a two-state solution and halt to civilian killings.', summary = 'Signed "An Open Letter From Jewish Elected Officials Regarding The War In Gaza" (Feb 2024) with Krueger, Hoylman-Sigal, Lander, and Restler. The letter condemned Hamas, criticized Netanyahu government for civilian deaths and settlement policy, called for hostage negotiations and a two-state solution. Source: https://www.nysenate.gov/newsroom/articles/2024/liz-krueger/open-letter-jewish-elected-officials-regarding-war-gaza', updated_at = NOW();
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (215, 11, 'Signed "An Open Letter From Jewish Elected Officials Regarding The War In Gaza" (Feb 2024) with Krueger, Hoylman-Sigal, Lander, and Restler. The letter condemned Hamas, criticized Netanyahu government') ON CONFLICT (person_id, criterion_id) DO NOTHING;
