INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (218, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Menin is the first Jewish NYC Council Speaker, went on an Israel solidarity trip visiting Kibbutz Kfar Aza, marched in the Israel Day Parade, introduced the buffer zone bill to protect synagogues from protests, and has been a vocal advocate against antisemitism and pro-Palestinian demonstrations.', 'Visited Kibbutz Kfar Aza on solidarity trip to Israel (Feb 2024). Marched in Israel Day Parade (May 2024). Introduced and passed buffer zone bill (Int. 1025) to limit protests near houses of worship, passed 44-5 in March 2026. Described as counterweight to Mayor Mamdani on Israel issues. Sources: https://forward.com/news/798894/julie-menin-council-mamdani-antisemitism/ ; https://www.jta.org/2026/03/26/ny/nyc-council-approves-buffer-zone-legislation-insulating-houses-of-worship-from-protests ; ht') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Menin is the first Jewish NYC Council Speaker, went on an Israel solidarity trip visiting Kibbutz Kfar Aza, marched in the Israel Day Parade, introduced the buffer zone bill to protect synagogues from protests, and has been a vocal advocate against antisemitism and pro-Palestinian demonstrations.', summary = 'Visited Kibbutz Kfar Aza on solidarity trip to Israel (Feb 2024). Marched in Israel Day Parade (May 2024). Introduced and passed buffer zone bill (Int. 1025) to limit protests near houses of worship, passed 44-5 in March 2026. Described as counterweight to Mayor Mamdani on Israel issues. Sources: https://forward.com/news/798894/julie-menin-council-mamdani-antisemitism/ ; https://www.jta.org/2026/03/26/ny/nyc-council-approves-buffer-zone-legislation-insulating-houses-of-worship-from-protests ; ht', updated_at = NOW();
