INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (219, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Brewer is a self-described strong supporter of the Jewish state, opposes BDS, has visited Israel multiple times including Iron Dome sites, though she has also acknowledged concerns about excessive Israeli military operations.', 'Opposes BDS. Has traveled to Israel multiple times with JCRC-NY. Expressed support for Iron Dome funding ("I''ve been twice to Iron Dome locations, and they''re miraculous"). In 2010, characterized Israeli military efforts as "excessive military operations in Palestine." Sources: https://jewishinsider.com/2021/12/gale-brewer-returns-to-the-city-council/ ; https://www.jcrcny.org/2010/01/from-nyc-councilmember-gale-brewer/ ; https://nyja.org/nyc-candidates/gale-brewer-2/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Brewer is a self-described strong supporter of the Jewish state, opposes BDS, has visited Israel multiple times including Iron Dome sites, though she has also acknowledged concerns about excessive Israeli military operations.', summary = 'Opposes BDS. Has traveled to Israel multiple times with JCRC-NY. Expressed support for Iron Dome funding ("I''ve been twice to Iron Dome locations, and they''re miraculous"). In 2010, characterized Israeli military efforts as "excessive military operations in Palestine." Sources: https://jewishinsider.com/2021/12/gale-brewer-returns-to-the-city-council/ ; https://www.jcrcny.org/2010/01/from-nyc-councilmember-gale-brewer/ ; https://nyja.org/nyc-candidates/gale-brewer-2/', updated_at = NOW();
