INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (220, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'Abreu has received backing from pro-Israel Solidarity PAC (~$8,100 in fundraisers), but was also listed on Canary Mission (a pro-Israel site that profiles pro-Palestine advocates), and left the Progressive Caucus in 2023. His actual stated position on the conflict is unclear and appears mixed.', 'Backed by Solidarity PAC, a pro-Israel group, with approximately $8,100 from fundraisers. Listed on Canary Mission, suggesting some pro-Palestine advocacy. Left the NYC Council Progressive Caucus in 2023, refusing to sign onto the group''s statement of principles. Sources: https://nysfocus.com/2025/03/20/new-york-city-council-mayor-election-israel-palestine ; https://canarymission.org/individual/Shaun_Abreu ; https://www.nysolidaritypac.org/2025-endorsed-candidates/shaun-abreu') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'Abreu has received backing from pro-Israel Solidarity PAC (~$8,100 in fundraisers), but was also listed on Canary Mission (a pro-Israel site that profiles pro-Palestine advocates), and left the Progressive Caucus in 2023. His actual stated position on the conflict is unclear and appears mixed.', summary = 'Backed by Solidarity PAC, a pro-Israel group, with approximately $8,100 from fundraisers. Listed on Canary Mission, suggesting some pro-Palestine advocacy. Left the NYC Council Progressive Caucus in 2023, refusing to sign onto the group''s statement of principles. Sources: https://nysfocus.com/2025/03/20/new-york-city-council-mayor-election-israel-palestine ; https://canarymission.org/individual/Shaun_Abreu ; https://www.nysolidaritypac.org/2025-endorsed-candidates/shaun-abreu', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (222, (SELECT id FROM topics WHERE slug = 'israel'), 'oppose', 'inferred', 'ai', 'Salaam called for an immediate ceasefire in Gaza on November 20, 2023, before even taking office, urging Biden to call on the Israeli government for "an immediate, durable and sustainable ceasefire."', 'Released statement on November 20, 2023 calling for ceasefire: "I join voices in Harlem, New York City & State, congressional representatives in Washington D.C., and the international community, in urging President Biden to do what''s right by calling on the Israeli government for an immediate, durable and sustainable ceasefire." Source: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'oppose', rationale = 'Salaam called for an immediate ceasefire in Gaza on November 20, 2023, before even taking office, urging Biden to call on the Israeli government for "an immediate, durable and sustainable ceasefire."', summary = 'Released statement on November 20, 2023 calling for ceasefire: "I join voices in Harlem, New York City & State, congressional representatives in Washington D.C., and the international community, in urging President Biden to do what''s right by calling on the Israeli government for an immediate, durable and sustainable ceasefire." Source: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', updated_at = NOW();
