INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (224, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Dinowitz is Chair of the Council Jewish Caucus, strongly condemned Hamas on Oct 7, denounced pro-Palestinian rallies, traveled to Israel visiting a kibbutz, sponsored the buffer zone bill for schools, received Solidarity PAC backing, and stood with CUNY professors who resigned over an anti-Israel union resolution.', 'Statement on Oct 7: "Hamas terrorists have infiltrated Israeli towns and launched thousands of missiles, including into Jerusalem. I proudly stand with Israel." Denounced pro-Palestinian rally following Oct 7. Sponsored buffer zone bill for educational institutions. Visited kibbutz in Israel. Supported CUNY professors who resigned over anti-Israel union resolution. Received ~$11,671 from Solidarity PAC-linked fundraisers. Sources: https://www.norwoodnews.org/update-dinowitz-hochul-others-denounc') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Dinowitz is Chair of the Council Jewish Caucus, strongly condemned Hamas on Oct 7, denounced pro-Palestinian rallies, traveled to Israel visiting a kibbutz, sponsored the buffer zone bill for schools, received Solidarity PAC backing, and stood with CUNY professors who resigned over an anti-Israel union resolution.', summary = 'Statement on Oct 7: "Hamas terrorists have infiltrated Israeli towns and launched thousands of missiles, including into Jerusalem. I proudly stand with Israel." Denounced pro-Palestinian rally following Oct 7. Sponsored buffer zone bill for educational institutions. Visited kibbutz in Israel. Supported CUNY professors who resigned over anti-Israel union resolution. Received ~$11,671 from Solidarity PAC-linked fundraisers. Sources: https://www.norwoodnews.org/update-dinowitz-hochul-others-denounc', updated_at = NOW();
