INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (225, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'Riley participated in a JCRC-organized trip to Israel in November 2022, suggesting engagement with the Jewish community and openness to Israel, but no public statements on the conflict were found.', 'Participated in a JCRC-NY organized "study tour" to Israel in late November 2022 (cost $5,000-$7,500 per person, paid by JCRC). Initially failed to disclose the trip on annual financial disclosure filings but said he would revise. Source: https://www.cityandstateny.com/politics/2023/06/some-nyc-council-members-didnt-disclose-their-free-tour-israel/387391/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'Riley participated in a JCRC-organized trip to Israel in November 2022, suggesting engagement with the Jewish community and openness to Israel, but no public statements on the conflict were found.', summary = 'Participated in a JCRC-NY organized "study tour" to Israel in late November 2022 (cost $5,000-$7,500 per person, paid by JCRC). Initially failed to disclose the trip on annual financial disclosure filings but said he would revise. Source: https://www.cityandstateny.com/politics/2023/06/some-nyc-council-members-didnt-disclose-their-free-tour-israel/387391/', updated_at = NOW();
