INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (232, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Paladino is a staunch pro-Israel Republican who has opposed ceasefire proposals, supported Israel''s military campaign, and strongly condemned Hamas. She stated a ceasefire should only come when "Hamas surrenders."', 'Paladino stated "We can have a ceasefire the minute Hamas surrenders" (Dec 2023). She opposed pro-Palestinian protests, defended Israel''s right to self-defense, and was endorsed by The Jewish Voice. She made controversial Islamophobic posts after the 2025 Bondi Beach shooting. Sources: https://qns.com/2023/12/brooklyn-council-member-taunts-vickie-paladino-in-dispute-over-possible-gaza-ceasefire/ ; https://tjvnews.com/news/politics/taking-a-bold-stand-against-the-socialist-surge-why-vickie-paladi') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Paladino is a staunch pro-Israel Republican who has opposed ceasefire proposals, supported Israel''s military campaign, and strongly condemned Hamas. She stated a ceasefire should only come when "Hamas surrenders."', summary = 'Paladino stated "We can have a ceasefire the minute Hamas surrenders" (Dec 2023). She opposed pro-Palestinian protests, defended Israel''s right to self-defense, and was endorsed by The Jewish Voice. She made controversial Islamophobic posts after the 2025 Bondi Beach shooting. Sources: https://qns.com/2023/12/brooklyn-council-member-taunts-vickie-paladino-in-dispute-over-possible-gaza-ceasefire/ ; https://tjvnews.com/news/politics/taking-a-bold-stand-against-the-socialist-surge-why-vickie-paladi', updated_at = NOW();
