INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (235, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'Caban was the first NYC Council member to call for a ceasefire (Oct 11, 2023), used the word "genocide," participated in JVP Grand Central protest, and has been one of the most vocal pro-Palestine voices on the Council as a DSA member.', 'On Oct 11, 2023, Caban tweeted: "Even as I continue to grieve the Israeli civilians murdered by Hamas, I feel mounting fear that the conditions for genocide in Gaza are developing." She participated in the JVP Grand Central Station protest and spoke at the 24-hour City Hall vigil. She was one of 17 council members supporting the ceasefire resolution. She is a DSA member. Sources: https://x.com/tiffany_caban/status/1712146243181277252 ; https://jacobin.com/2023/11/socialist-city-councillors-new-y') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'Caban was the first NYC Council member to call for a ceasefire (Oct 11, 2023), used the word "genocide," participated in JVP Grand Central protest, and has been one of the most vocal pro-Palestine voices on the Council as a DSA member.', summary = 'On Oct 11, 2023, Caban tweeted: "Even as I continue to grieve the Israeli civilians murdered by Hamas, I feel mounting fear that the conditions for genocide in Gaza are developing." She participated in the JVP Grand Central Station protest and spoke at the 24-hour City Hall vigil. She was one of 17 council members supporting the ceasefire resolution. She is a DSA member. Sources: https://x.com/tiffany_caban/status/1712146243181277252 ; https://jacobin.com/2023/11/socialist-city-councillors-new-y', updated_at = NOW();
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (235, 9, 'On Oct 11, 2023, Caban tweeted: "Even as I continue to grieve the Israeli civilians murdered by Hamas, I feel mounting fear that the conditions for genocide in Gaza are developing." She participated i') ON CONFLICT (person_id, criterion_id) DO NOTHING;
