INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (237, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Gennaro has been described as a "passionate fighter for Israel" with strong Orthodox Jewish community support, attended pro-Israel vigils, and has stood with the pro-Israel community his entire career.', 'Gennaro was described as a "passionate fighter for Israel" who "has proudly stood with the pro-Israel community his entire career." He spoke at a vigil at Kew Gardens Library with the Queens Jewish Community Council after Oct 7. He defeated a progressive anti-Israel candidate in a 2021 special election. His district includes a sizable Orthodox Jewish community. Sources: https://hamodia.com/2021/02/02/james-f-gennaro-set-win-special-election-city-council-24th-district/ ; https://www.qchron.com/ed') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Gennaro has been described as a "passionate fighter for Israel" with strong Orthodox Jewish community support, attended pro-Israel vigils, and has stood with the pro-Israel community his entire career.', summary = 'Gennaro was described as a "passionate fighter for Israel" who "has proudly stood with the pro-Israel community his entire career." He spoke at a vigil at Kew Gardens Library with the Queens Jewish Community Council after Oct 7. He defeated a progressive anti-Israel candidate in a 2021 special election. His district includes a sizable Orthodox Jewish community. Sources: https://hamodia.com/2021/02/02/james-f-gennaro-set-win-special-election-city-council-24th-district/ ; https://www.qchron.com/ed', updated_at = NOW();
