INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (240, (SELECT id FROM topics WHERE slug = 'israel'), 'oppose', 'inferred', 'ai', 'Williams wore a "Ceasefire Now" button at the Dec 2023 Council meeting, signed the Local Progress ceasefire letter, and was one of 17 Council members supporting the ceasefire resolution.', 'Williams wore a "Ceasefire Now" button on Dec 6, 2023. She signed the Local Progress ceasefire letter on Jan 9, 2024. She welcomed the Jan 2025 ceasefire, saying "the halting of violence and return of hostages are what people from across the city and the world have prayed and protested for." She was listed among 17 ceasefire supporters. Sources: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/ ; https://advocate.nyc.gov/press/williams-resp') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'oppose', rationale = 'Williams wore a "Ceasefire Now" button at the Dec 2023 Council meeting, signed the Local Progress ceasefire letter, and was one of 17 Council members supporting the ceasefire resolution.', summary = 'Williams wore a "Ceasefire Now" button on Dec 6, 2023. She signed the Local Progress ceasefire letter on Jan 9, 2024. She welcomed the Jan 2025 ceasefire, saying "the halting of violence and return of hostages are what people from across the city and the world have prayed and protested for." She was listed among 17 ceasefire supporters. Sources: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/ ; https://advocate.nyc.gov/press/williams-resp', updated_at = NOW();
