INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (242, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Schulman is Vice Chair of the NYC Council Jewish Caucus (whose mission includes supporting Israel), received backing from the pro-Israel Solidarity PAC, and has advocated for antisemitism protections including threatening to override mayoral vetoes.', 'Schulman is Vice Chair of the Council''s Jewish Caucus, which is "dedicated to...supporting Israel." She received backing from Solidarity PAC, a pro-Israel PAC. She stated she was "prepared to whip the votes needed to override a veto on antisemitism-related legislation" in response to Mayor Mamdani''s revocation of pro-Israel executive orders. Sources: https://council.nyc.gov/caucuses/jewish-caucus/ ; https://nysfocus.com/2025/03/20/new-york-city-council-mayor-election-israel-palestine ; https://w') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Schulman is Vice Chair of the NYC Council Jewish Caucus (whose mission includes supporting Israel), received backing from the pro-Israel Solidarity PAC, and has advocated for antisemitism protections including threatening to override mayoral vetoes.', summary = 'Schulman is Vice Chair of the Council''s Jewish Caucus, which is "dedicated to...supporting Israel." She received backing from Solidarity PAC, a pro-Israel PAC. She stated she was "prepared to whip the votes needed to override a veto on antisemitism-related legislation" in response to Mayor Mamdani''s revocation of pro-Israel executive orders. Sources: https://council.nyc.gov/caucuses/jewish-caucus/ ; https://nysfocus.com/2025/03/20/new-york-city-council-mayor-election-israel-palestine ; https://w', updated_at = NOW();
