INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (245, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Ariola is the Republican minority leader who condemned pro-Palestinian rallies, issued a joint statement against DSA''s pro-Hamas rally, attended pro-Israel prayer events, and sought information about mayoral executive orders revoking anti-BDS protections.', 'On Oct 10, 2023, Ariola released a joint statement with the Common-Sense Caucus condemning DSA for promoting a "pro-Hamas rally." She prayed at Howard Beach Judea Center for Israel. As minority leader, she filed FOIL requests about Mayor Mamdani''s revocation of anti-BDS executive orders. Sources: http://theforumnewsgroup.com/2023/10/13/pols-rally-around-israel/ ; https://qns.com/2026/01/ariola-republicans-foil-request-executive-orders/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Ariola is the Republican minority leader who condemned pro-Palestinian rallies, issued a joint statement against DSA''s pro-Hamas rally, attended pro-Israel prayer events, and sought information about mayoral executive orders revoking anti-BDS protections.', summary = 'On Oct 10, 2023, Ariola released a joint statement with the Common-Sense Caucus condemning DSA for promoting a "pro-Hamas rally." She prayed at Howard Beach Judea Center for Israel. As minority leader, she filed FOIL requests about Mayor Mamdani''s revocation of anti-BDS executive orders. Sources: http://theforumnewsgroup.com/2023/10/13/pols-rally-around-israel/ ; https://qns.com/2026/01/ariola-republicans-foil-request-executive-orders/', updated_at = NOW();
