INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (247, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'Gutierrez wore a "Ceasefire Now" shirt at the Dec 2023 Council meeting, signed the JVP open letter to Biden calling for ceasefire, abstained from the "End Jew Hatred" resolution, and was a prominent ceasefire advocate.', 'On Dec 6, 2023, Gutierrez wore a "Ceasefire Now" shirt at a Stated Meeting, posting: "Proud to stand in solidarity with some of my @nyccouncil colleagues today...calling for an immediate and permanent #ceasefire." She signed the JVP Action open letter to Biden calling for ceasefire. She abstained from the "End Jew Hatred Day" resolution (April 2023). She was one of 17 council members supporting the ceasefire resolution. Sources: https://worldisraelnews.com/anti-israel-nyc-council-members-ripped-') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'Gutierrez wore a "Ceasefire Now" shirt at the Dec 2023 Council meeting, signed the JVP open letter to Biden calling for ceasefire, abstained from the "End Jew Hatred" resolution, and was a prominent ceasefire advocate.', summary = 'On Dec 6, 2023, Gutierrez wore a "Ceasefire Now" shirt at a Stated Meeting, posting: "Proud to stand in solidarity with some of my @nyccouncil colleagues today...calling for an immediate and permanent #ceasefire." She signed the JVP Action open letter to Biden calling for ceasefire. She abstained from the "End Jew Hatred Day" resolution (April 2023). She was one of 17 council members supporting the ceasefire resolution. Sources: https://worldisraelnews.com/anti-israel-nyc-council-members-ripped-', updated_at = NOW();
