INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (248, (SELECT id FROM topics WHERE slug = 'israel'), 'oppose', 'inferred', 'ai', 'Hudson signed the Local Progress ceasefire letter and was listed among the 17 council members supporting the ceasefire resolution, though she has been less vocal than some colleagues.', 'Hudson signed the Local Progress letter on Jan 9, 2024, calling for "a durable ceasefire." She was one of 17 council members listed as supporting the ceasefire resolution. Source: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'oppose', rationale = 'Hudson signed the Local Progress ceasefire letter and was listed among the 17 council members supporting the ceasefire resolution, though she has been less vocal than some colleagues.', summary = 'Hudson signed the Local Progress letter on Jan 9, 2024, calling for "a durable ceasefire." She was one of 17 council members listed as supporting the ceasefire resolution. Source: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', updated_at = NOW();
