INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (249, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'Osse is a DSA member who called for a ceasefire, participated in the JVP Grand Central protest, wore a "Ceasefire Now" shirt at Council, and issued a statement calling occupation the "primary root of violence" while affirming Palestinian liberation as legitimate.', 'Osse participated in the JVP Grand Central Station ceasefire protest (Oct 2023). He wore a "Ceasefire Now" shirt at the Dec 6, 2023 Council meeting. His Oct 2023 statement declared Israel''s "occupation" was the "primary root of the violence" and, while criticizing terrorism, said "the Palestinian movement for national liberation is legitimate." He was one of 17 council members supporting the ceasefire resolution. He is a DSA member. Sources: https://www.cityandstateny.com/politics/2024/03/new-yo') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'Osse is a DSA member who called for a ceasefire, participated in the JVP Grand Central protest, wore a "Ceasefire Now" shirt at Council, and issued a statement calling occupation the "primary root of violence" while affirming Palestinian liberation as legitimate.', summary = 'Osse participated in the JVP Grand Central Station ceasefire protest (Oct 2023). He wore a "Ceasefire Now" shirt at the Dec 6, 2023 Council meeting. His Oct 2023 statement declared Israel''s "occupation" was the "primary root of the violence" and, while criticizing terrorism, said "the Palestinian movement for national liberation is legitimate." He was one of 17 council members supporting the ceasefire resolution. He is a DSA member. Sources: https://www.cityandstateny.com/politics/2024/03/new-yo', updated_at = NOW();
