INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (250, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'Nurse was co-chair of the Council Progressive Caucus, called for ceasefire on Oct 12, 2023, voted against the "End Jew Hatred" resolution, and participated in the JVP Grand Central protest.', 'Nurse called for a ceasefire on Oct 12, 2023, criticizing Governor Hochul for not supporting Palestinian New Yorkers. She participated in the JVP Grand Central Station protest. She was one of only two council members to vote "no" on the "End Jew Hatred Day" resolution (with Shahana Hanif). She was one of 17 council members supporting the ceasefire resolution. Sources: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/ ; https://forward.com/f') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'Nurse was co-chair of the Council Progressive Caucus, called for ceasefire on Oct 12, 2023, voted against the "End Jew Hatred" resolution, and participated in the JVP Grand Central protest.', summary = 'Nurse called for a ceasefire on Oct 12, 2023, criticizing Governor Hochul for not supporting Palestinian New Yorkers. She participated in the JVP Grand Central Station protest. She was one of only two council members to vote "no" on the "End Jew Hatred Day" resolution (with Shahana Hanif). She was one of 17 council members supporting the ceasefire resolution. Sources: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/ ; https://forward.com/f', updated_at = NOW();
