INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (251, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'Aviles is a DSA member who supports BDS, signed the JVP ceasefire letter, abstained from the "End Jew Hatred" resolution, and has been one of the most vocal pro-Palestine council members.', 'Aviles signed a JVP Action letter calling for immediate and permanent ceasefire. She supports the BDS movement targeting Israel. She abstained from the "End Jew Hatred Day" resolution. She is a DSA member. She wrote an op-ed in City & State titled "From Puerto Rico to Palestine" criticizing US military funding for Israel. Pro-Israel activists backed challenger Ling Ye to unseat her. Sources: https://jewishinsider.com/2025/06/ling-ye-alexa-aviles-dan-goldman-south-brooklyn-council-primary/ ; http') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'Aviles is a DSA member who supports BDS, signed the JVP ceasefire letter, abstained from the "End Jew Hatred" resolution, and has been one of the most vocal pro-Palestine council members.', summary = 'Aviles signed a JVP Action letter calling for immediate and permanent ceasefire. She supports the BDS movement targeting Israel. She abstained from the "End Jew Hatred Day" resolution. She is a DSA member. She wrote an op-ed in City & State titled "From Puerto Rico to Palestine" criticizing US military funding for Israel. Pro-Israel activists backed challenger Ling Ye to unseat her. Sources: https://jewishinsider.com/2025/06/ling-ye-alexa-aviles-dan-goldman-south-brooklyn-council-primary/ ; http', updated_at = NOW();
