INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (252, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'Hanif is among the most vocal anti-Israel members of the Council, having used the terms "genocide" and "apartheid," been arrested at a pro-Palestinian rally, voted against "End Jew Hatred Day," and endorsed the "Leave It Blank" campaign against Biden over Gaza policy.', 'Hanif was arrested at an Oct 2023 rally organized by Within Our Lifetime and DSA calling for ceasefire. She tweeted demanding "an end to the apartheid and genocide" (Oct 23, 2023). She called Israel''s actions a "genocide." She voted against the "End Jew Hatred Day" resolution. She endorsed the "Leave It Blank" campaign against Biden over Gaza. Her initial Oct 13, 2023 statement called occupation the "root cause" without immediately condemning Hamas (though she later issued a condemnation). Pro-I') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'Hanif is among the most vocal anti-Israel members of the Council, having used the terms "genocide" and "apartheid," been arrested at a pro-Palestinian rally, voted against "End Jew Hatred Day," and endorsed the "Leave It Blank" campaign against Biden over Gaza policy.', summary = 'Hanif was arrested at an Oct 2023 rally organized by Within Our Lifetime and DSA calling for ceasefire. She tweeted demanding "an end to the apartheid and genocide" (Oct 23, 2023). She called Israel''s actions a "genocide." She voted against the "End Jew Hatred Day" resolution. She endorsed the "Leave It Blank" campaign against Biden over Gaza. Her initial Oct 13, 2023 statement called occupation the "root cause" without immediately condemning Hamas (though she later issued a condemnation). Pro-I', updated_at = NOW();
