INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (253, (SELECT id FROM topics WHERE slug = 'israel'), 'oppose', 'inferred', 'ai', 'Joseph was listed among the 17 council members supporting the ceasefire resolution and spoke at the 24-hour City Hall vigil in support of a ceasefire, though she abstained from the "End Jew Hatred" vote claiming she didn''t have time to review it.', 'Joseph spoke at a 24-hour vigil at City Hall on Feb 28, 2024, in support of a ceasefire. She was one of 17 council members listed as supporting the ceasefire resolution. She abstained from the "End Jew Hatred Day" resolution, tweeting she "regretfully abstained" because she "didn''t have a chance to review it." Sources: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/ ; https://forward.com/fast-forward/544960/new-york-city-council-end-jew-h') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'oppose', rationale = 'Joseph was listed among the 17 council members supporting the ceasefire resolution and spoke at the 24-hour City Hall vigil in support of a ceasefire, though she abstained from the "End Jew Hatred" vote claiming she didn''t have time to review it.', summary = 'Joseph spoke at a 24-hour vigil at City Hall on Feb 28, 2024, in support of a ceasefire. She was one of 17 council members listed as supporting the ceasefire resolution. She abstained from the "End Jew Hatred Day" resolution, tweeting she "regretfully abstained" because she "didn''t have a chance to review it." Sources: https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/ ; https://forward.com/fast-forward/544960/new-york-city-council-end-jew-h', updated_at = NOW();
