INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (256, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Zhuang received backing from Solidarity PAC, a pro-Israel political action committee, and is described as a conservative Democrat. She was not among ceasefire advocates.', 'Solidarity PAC, a pro-Israel PAC described as a local version of AIPAC/DMFI, backed Zhuang''s candidacy. She is described as a conservative Democrat. She was not among the council members who called for a ceasefire. Source: https://nysfocus.com/2025/03/20/new-york-city-council-mayor-election-israel-palestine') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Zhuang received backing from Solidarity PAC, a pro-Israel political action committee, and is described as a conservative Democrat. She was not among ceasefire advocates.', summary = 'Solidarity PAC, a pro-Israel PAC described as a local version of AIPAC/DMFI, backed Zhuang''s candidacy. She is described as a conservative Democrat. She was not among the council members who called for a ceasefire. Source: https://nysfocus.com/2025/03/20/new-york-city-council-mayor-election-israel-palestine', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (257, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Felder is a conservative Democrat from Borough Park representing a large Orthodox Jewish constituency, has a long history of supporting Israel, and previously blocked UN renovation plans calling the UN "anti-Israel."', 'Felder represents Borough Park, home to a large Orthodox Jewish community. During his prior Council service (2002-2010), he blocked UN headquarters renovation plans calling the UN "anti-American and anti-Israel." He returned to the Council in a 2025 special election winning 81% of the vote. He is a member of the Council''s Jewish Caucus. Sources: https://en.wikipedia.org/wiki/Simcha_Felder ; https://council.nyc.gov/caucuses/jewish-caucus/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Felder is a conservative Democrat from Borough Park representing a large Orthodox Jewish constituency, has a long history of supporting Israel, and previously blocked UN renovation plans calling the UN "anti-Israel."', summary = 'Felder represents Borough Park, home to a large Orthodox Jewish community. During his prior Council service (2002-2010), he blocked UN headquarters renovation plans calling the UN "anti-American and anti-Israel." He returned to the Council in a 2025 special election winning 81% of the vote. He is a member of the Council''s Jewish Caucus. Sources: https://en.wikipedia.org/wiki/Simcha_Felder ; https://council.nyc.gov/caucuses/jewish-caucus/', updated_at = NOW();
