INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (258, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Louis has stated she supports Israel and opposes BDS, has strong Jewish community backing including the Flatbush Jewish Community Coalition endorsement, and has consistently denounced antisemitism.', 'Louis assured Jewish leaders she supports the State of Israel and opposes BDS. She received endorsements from eight Jewish politicians and the Flatbush Jewish Community Coalition. She has issued multiple statements condemning antisemitic attacks in her district. Her district includes large Jewish populations in Flatbush and Midwood. Sources: https://www.theyeshivaworld.com/news/general/1747016/hate-loses-in-flatbush-jewish-community-backed-farah-louis-wins-council-race.html ; https://www.jewishp') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Louis has stated she supports Israel and opposes BDS, has strong Jewish community backing including the Flatbush Jewish Community Coalition endorsement, and has consistently denounced antisemitism.', summary = 'Louis assured Jewish leaders she supports the State of Israel and opposes BDS. She received endorsements from eight Jewish politicians and the Flatbush Jewish Community Coalition. She has issued multiple statements condemning antisemitic attacks in her district. Her district includes large Jewish populations in Flatbush and Midwood. Sources: https://www.theyeshivaworld.com/news/general/1747016/hate-loses-in-flatbush-jewish-community-backed-farah-louis-wins-council-race.html ; https://www.jewishp', updated_at = NOW();
