INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (259, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'Narcisse expressed sympathy for both sides, noting the "devastating loss of life" on both sides while emphasizing "shared humanity." She did not take a strong pro-Israel or pro-Palestine position.', 'Narcisse stated she was "deeply saddened by devastating loss of life on both sides" and said "it''s more important than ever to remember our shared humanity and the bonds that unite us." She noted Brooklyn is home to the largest Jewish population outside Israel and extended compassion to affected communities. Source: https://www.caribbeanlife.com/narcisse-deeply-saddened-by-devastating-loss-of-life-on-both-sides-in-israeli-hamas-war/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'Narcisse expressed sympathy for both sides, noting the "devastating loss of life" on both sides while emphasizing "shared humanity." She did not take a strong pro-Israel or pro-Palestine position.', summary = 'Narcisse stated she was "deeply saddened by devastating loss of life on both sides" and said "it''s more important than ever to remember our shared humanity and the bonds that unite us." She noted Brooklyn is home to the largest Jewish population outside Israel and extended compassion to affected communities. Source: https://www.caribbeanlife.com/narcisse-deeply-saddened-by-devastating-loss-of-life-on-both-sides-in-israeli-hamas-war/', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (260, (SELECT id FROM topics WHERE slug = 'israel'), 'oppose', 'inferred', 'ai', 'Santosuosso has deep ties to the Arab American community in Bay Ridge, previously worked for the Arab American Association under Linda Sarsour, worked in Palestine, and expressed empathy for Bay Ridge''s Palestinian community''s anger over Gaza. Her predecessor Justin Brannan supported the ceasefire resolution.', 'Santosuosso worked at the Arab American Association of New York under Linda Sarsour and for the Palestine Wildlife Society in Beit Sahour, Palestine. She worked on Palestinian pastor Khader El-Yateem''s City Council campaign. She stated the Bay Ridge Palestinian and Arab American communities are "horrified and angry" about Israel''s war in Gaza and said she would protect their right to protest. She worked at the Arava Institute in Israel (a peace/environment organization). She speaks Arabic. Her p') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'oppose', rationale = 'Santosuosso has deep ties to the Arab American community in Bay Ridge, previously worked for the Arab American Association under Linda Sarsour, worked in Palestine, and expressed empathy for Bay Ridge''s Palestinian community''s anger over Gaza. Her predecessor Justin Brannan supported the ceasefire resolution.', summary = 'Santosuosso worked at the Arab American Association of New York under Linda Sarsour and for the Palestine Wildlife Society in Beit Sahour, Palestine. She worked on Palestinian pastor Khader El-Yateem''s City Council campaign. She stated the Bay Ridge Palestinian and Arab American communities are "horrified and angry" about Israel''s war in Gaza and said she would protect their right to protest. She worked at the Arava Institute in Israel (a peace/environment organization). She speaks Arabic. Her p', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (261, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Vernikov is the most vocal pro-Israel member of the NYC Council, having worn an Israeli flag dress, attended pro-Israel counter-protests (bringing a gun to one), quit the women''s caucus over hostage rhetoric, and been a leading voice against antisemitism.', 'Vernikov attended a pro-Israel counter-protest at Brooklyn College (Oct 2023), where she was controversially arrested for carrying a firearm (charges later dropped). She wore an Israeli flag dress to the NY Young Republican Club Gala. She quit the Council''s women''s caucus citing rhetoric on Israeli hostages. She has been described as "a leading voice against Antisemitism" on the Council. She is Republican minority whip. Sources: https://forward.com/fast-forward/564702/jewish-nyc-councilwoman-inn') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Vernikov is the most vocal pro-Israel member of the NYC Council, having worn an Israeli flag dress, attended pro-Israel counter-protests (bringing a gun to one), quit the women''s caucus over hostage rhetoric, and been a leading voice against antisemitism.', summary = 'Vernikov attended a pro-Israel counter-protest at Brooklyn College (Oct 2023), where she was controversially arrested for carrying a firearm (charges later dropped). She wore an Israeli flag dress to the NY Young Republican Club Gala. She quit the Council''s women''s caucus citing rhetoric on Israeli hostages. She has been described as "a leading voice against Antisemitism" on the Council. She is Republican minority whip. Sources: https://forward.com/fast-forward/564702/jewish-nyc-councilwoman-inn', updated_at = NOW();
