INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (262, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Hanks traveled to Israel on a solidarity trip in February 2024, visiting Kibbutz Kfar Aza, and participated in Staten Island solidarity events for Israel. This was her second trip to Israel in three years.', 'Hanks traveled to Israel on a three-day solidarity trip in February 2024, visiting communities devastated on Oct 7 including Kibbutz Kfar Aza, where she said "I come from a rough neighborhood in Staten Island so I know a little about living in fear, but nothing like this." This was her second Israel trip in three years. Local pro-Palestine groups organized a protest at her district office in response. Sources: https://www.pleaforthefifth.com/constituents_speak_out_on_councilperson_kamillah_hanks') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Hanks traveled to Israel on a solidarity trip in February 2024, visiting Kibbutz Kfar Aza, and participated in Staten Island solidarity events for Israel. This was her second trip to Israel in three years.', summary = 'Hanks traveled to Israel on a three-day solidarity trip in February 2024, visiting communities devastated on Oct 7 including Kibbutz Kfar Aza, where she said "I come from a rough neighborhood in Staten Island so I know a little about living in fear, but nothing like this." This was her second Israel trip in three years. Local pro-Palestine groups organized a protest at her district office in response. Sources: https://www.pleaforthefifth.com/constituents_speak_out_on_councilperson_kamillah_hanks', updated_at = NOW();
