INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (7, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Primary sponsor of antisemitism bill S531, Chair of Senate Republican Antisemitism Working Group, previously introduced legislation to defund pro-BDS student groups, and strongly advocated for Israel at hostage rallies.', 'Primary sponsor of S531 (antisemitism vandalism act protecting pro-Israel materials). Chair of Senate Republican Antisemitism Working Group. Previously introduced bill to defund campus BDS organizations. Stated at hostage rally: "Releasing those hostages is the beginning of bringing peace." Sources: https://www.nysenate.gov/legislation/bills/2025/S531 ; https://mondoweiss.net/2016/06/senator-university-funds/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Primary sponsor of antisemitism bill S531, Chair of Senate Republican Antisemitism Working Group, previously introduced legislation to defund pro-BDS student groups, and strongly advocated for Israel at hostage rallies.', summary = 'Primary sponsor of S531 (antisemitism vandalism act protecting pro-Israel materials). Chair of Senate Republican Antisemitism Working Group. Previously introduced bill to defund campus BDS organizations. Stated at hostage rally: "Releasing those hostages is the beginning of bringing peace." Sources: https://www.nysenate.gov/legislation/bills/2025/S531 ; https://mondoweiss.net/2016/06/senator-university-funds/', updated_at = NOW();
