INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (8, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Republican senator who participated in hostage release advocacy alongside Run For Their Lives and Senate Republican Conference, though limited individual public statements on Israel found.', 'Joined Run for Their Lives advocates and families of hostages taken during Oct 7 terrorist attack in support of their immediate release. Part of Senate Republican Conference that unveiled antisemitism report. Source: https://www.nysenate.gov/newsroom/press-releases/2024/mario-r-mattera/senate-minority-conference-joins-run-their-lives') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Republican senator who participated in hostage release advocacy alongside Run For Their Lives and Senate Republican Conference, though limited individual public statements on Israel found.', summary = 'Joined Run for Their Lives advocates and families of hostages taken during Oct 7 terrorist attack in support of their immediate release. Part of Senate Republican Conference that unveiled antisemitism report. Source: https://www.nysenate.gov/newsroom/press-releases/2024/mario-r-mattera/senate-minority-conference-joins-run-their-lives', updated_at = NOW();
