INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (9, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Member of Senate Republican Antisemitism Working Group, cosponsored S531, led letter to Governor to help New Yorkers stranded in Israel, and actively worked on antisemitism legislation.', 'Member of Senate Republican Antisemitism Working Group. Cosponsored S531 (antisemitism vandalism act). Led letter with Minority Leader Ortt urging Governor to help New Yorkers stranded in Israel. Co-unveiled 2023-2024 antisemitism report. Sources: https://www.nysenate.gov/newsroom/press-releases/2025/patricia-canzoneri-fitzpatrick/senator-canzoneri-fitzpatrick-minority ; https://www.nysenate.gov/newsroom/press-releases/2024/patricia-canzoneri-fitzpatrick/sen-canzoneri-fitzpatrick-republican') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Member of Senate Republican Antisemitism Working Group, cosponsored S531, led letter to Governor to help New Yorkers stranded in Israel, and actively worked on antisemitism legislation.', summary = 'Member of Senate Republican Antisemitism Working Group. Cosponsored S531 (antisemitism vandalism act). Led letter with Minority Leader Ortt urging Governor to help New Yorkers stranded in Israel. Co-unveiled 2023-2024 antisemitism report. Sources: https://www.nysenate.gov/newsroom/press-releases/2025/patricia-canzoneri-fitzpatrick/senator-canzoneri-fitzpatrick-minority ; https://www.nysenate.gov/newsroom/press-releases/2024/patricia-canzoneri-fitzpatrick/sen-canzoneri-fitzpatrick-republican', updated_at = NOW();
