INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (11, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Jewish Democratic senator who sponsored legislation protecting Jewish and pro-Israel students on college campuses from antisemitism and discrimination, and spoke on Israel resolution during Senate session.', 'Sponsored legislation with Assemblywoman Rozic to protect Jewish and pro-Israel students on college campuses, which passed unanimously with bipartisan support. Spoke on Israel resolution during Senate session. Sources: https://assembly.state.ny.us/mem/Nily-Rozic/story/114300 ; https://www.nysenate.gov/newsroom/video/toby-ann-stavisky/sen-stavisky-speaks-israel-resolution-during-session') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Jewish Democratic senator who sponsored legislation protecting Jewish and pro-Israel students on college campuses from antisemitism and discrimination, and spoke on Israel resolution during Senate session.', summary = 'Sponsored legislation with Assemblywoman Rozic to protect Jewish and pro-Israel students on college campuses, which passed unanimously with bipartisan support. Spoke on Israel resolution during Senate session. Sources: https://assembly.state.ny.us/mem/Nily-Rozic/story/114300 ; https://www.nysenate.gov/newsroom/video/toby-ann-stavisky/sen-stavisky-speaks-israel-resolution-during-session', updated_at = NOW();
