INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (13, (SELECT id FROM topics WHERE slug = 'israel'), 'oppose', 'inferred', 'ai', 'Called for a permanent ceasefire in Gaza, advocated for Palestinian speaking slot at DNC, and has been described as a longtime pro-Palestinian advocate.', 'Released statement on March 13, 2024 calling for a permanent ceasefire in Gaza, saying she stands "for de-escalation, diplomacy and human rights for all people — Palestinian and Israeli." Joined call for DNC to give Palestinian a speaking slot. Described as a longtime pro-Palestinian advocate. Sources: https://medium.com/@jessica_ramos/ramosceasefirestatement-839bb35c22e7 ; https://www.cityandstateny.com/politics/2024/08/ny-elected-officials-call-dnc-give-speaking-slot-palestinian/399015/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'oppose', rationale = 'Called for a permanent ceasefire in Gaza, advocated for Palestinian speaking slot at DNC, and has been described as a longtime pro-Palestinian advocate.', summary = 'Released statement on March 13, 2024 calling for a permanent ceasefire in Gaza, saying she stands "for de-escalation, diplomacy and human rights for all people — Palestinian and Israeli." Joined call for DNC to give Palestinian a speaking slot. Described as a longtime pro-Palestinian advocate. Sources: https://medium.com/@jessica_ramos/ramosceasefirestatement-839bb35c22e7 ; https://www.cityandstateny.com/politics/2024/08/ny-elected-officials-call-dnc-give-speaking-slot-palestinian/399015/', updated_at = NOW();
