INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (15, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Primary sponsor of anti-BDS bill S1255 to prohibit NY from contracting with companies boycotting Israel, and publicly condemned DSA''s anti-Israel boycott questionnaire as antisemitic.', 'Primary sponsor of S1255 (anti-BDS purchasing restrictions bill). In 2020, spoke out against DSA questionnaire asking council members to boycott Israel trip, calling it "not only wrong, it is Anti-Semitic." Sources: https://www.nysenate.gov/legislation/bills/2025/S1255 ; https://www.nysenate.gov/newsroom/press-releases/2020/joseph-addabbo/addabbo-speaks-out-against-dsa-anti-semitic-question') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Primary sponsor of anti-BDS bill S1255 to prohibit NY from contracting with companies boycotting Israel, and publicly condemned DSA''s anti-Israel boycott questionnaire as antisemitic.', summary = 'Primary sponsor of S1255 (anti-BDS purchasing restrictions bill). In 2020, spoke out against DSA questionnaire asking council members to boycott Israel trip, calling it "not only wrong, it is Anti-Semitic." Sources: https://www.nysenate.gov/legislation/bills/2025/S1255 ; https://www.nysenate.gov/newsroom/press-releases/2020/joseph-addabbo/addabbo-speaks-out-against-dsa-anti-semitic-question', updated_at = NOW();
