INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (16, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Described as pro-Israel by multiple sources; endorsed Mamdani for mayor despite acknowledging a "big disagreement" on Israel, indicating Liu supports Israel while Mamdani is critical of it.', 'When endorsing Mamdani for mayor, Liu explicitly acknowledged their "big disagreement" on Israel, with Liu being described as "pro-Israel" while Mamdani is "fiercely critical" of Israel''s government. Liu did not call for ceasefire and is not on ceasefire lists. Source: https://www.amny.com/news/queens-liu-endorses-mamdani-disagreement-israel/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Described as pro-Israel by multiple sources; endorsed Mamdani for mayor despite acknowledging a "big disagreement" on Israel, indicating Liu supports Israel while Mamdani is critical of it.', summary = 'When endorsing Mamdani for mayor, Liu explicitly acknowledged their "big disagreement" on Israel, with Liu being described as "pro-Israel" while Mamdani is "fiercely critical" of Israel''s government. Liu did not call for ceasefire and is not on ceasefire lists. Source: https://www.amny.com/news/queens-liu-endorses-mamdani-disagreement-israel/', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (18, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'DSA member who supports BDS, co-sponsors "Not On Our Dime" bill S606, called for immediate ceasefire, used "genocide" and "apartheid" language regarding Israel, and was an early and vocal advocate for Palestinian liberation.', 'Cosponsor of S606 "Not On Our Dime" act. Supports BDS movement. Called for ceasefire on Oct 13, 2023. Wrote in Jacobin: "refuse to let our grief be weaponized to justify a genocide in Gaza." Posted on X accusing Israel of "occupation and apartheid." DSA member. Fired staffer who endorsed Oct 7 attack but continued pro-Palestinian advocacy. Sources: https://jacobin.com/2023/10/julia-salazar-palestinians-liberation-cease-fire-israeli-occupation ; https://canarymission.org/individual/Julia_Salazar') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'DSA member who supports BDS, co-sponsors "Not On Our Dime" bill S606, called for immediate ceasefire, used "genocide" and "apartheid" language regarding Israel, and was an early and vocal advocate for Palestinian liberation.', summary = 'Cosponsor of S606 "Not On Our Dime" act. Supports BDS movement. Called for ceasefire on Oct 13, 2023. Wrote in Jacobin: "refuse to let our grief be weaponized to justify a genocide in Gaza." Posted on X accusing Israel of "occupation and apartheid." DSA member. Fired staffer who endorsed Oct 7 attack but continued pro-Palestinian advocacy. Sources: https://jacobin.com/2023/10/julia-salazar-palestinians-liberation-cease-fire-israeli-occupation ; https://canarymission.org/individual/Julia_Salazar', updated_at = NOW();
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (18, 3, 'Cosponsor of S606 "Not On Our Dime" act. Supports BDS movement. Called for ceasefire on Oct 13, 2023. Wrote in Jacobin: "refuse to let our grief be weaponized to justify a genocide in Gaza." Posted on') ON CONFLICT (person_id, criterion_id) DO NOTHING;
