INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (20, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Condemned Hamas'' Oct 7 attack, affirmed Israel''s right to self-defense, condemned anti-Jewish harassment at pro-Palestinian protests, and courted Orthodox Jewish voters in his mayoral campaign. Has not called for ceasefire.', 'On Oct 7, stated: "Israel has the right to defend itself, and I pray it does so in a way that increases the chances of an eventual lasting peace." Condemned pro-Palestinian demonstrations that harassed Jewish people in Borough Park and Brooklyn Museum. Courted Crown Heights Chabad community. Did not appear on ceasefire call lists. Sources: https://www.jta.org/2024/09/27/ny/where-do-nyc-mayor-eric-adams-potential-successors-stand-on-israel-and-jewish-issues ; https://www.jta.org/2025/03/12/ny/a-j') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Condemned Hamas'' Oct 7 attack, affirmed Israel''s right to self-defense, condemned anti-Jewish harassment at pro-Palestinian protests, and courted Orthodox Jewish voters in his mayoral campaign. Has not called for ceasefire.', summary = 'On Oct 7, stated: "Israel has the right to defend itself, and I pray it does so in a way that increases the chances of an eventual lasting peace." Condemned pro-Palestinian demonstrations that harassed Jewish people in Borough Park and Brooklyn Museum. Courted Crown Heights Chabad community. Did not appear on ceasefire call lists. Sources: https://www.jta.org/2024/09/27/ny/where-do-nyc-mayor-eric-adams-potential-successors-stand-on-israel-and-jewish-issues ; https://www.jta.org/2025/03/12/ny/a-j', updated_at = NOW();
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (20, 12, 'On Oct 7, stated: "Israel has the right to defend itself, and I pray it does so in a way that increases the chances of an eventual lasting peace." Condemned pro-Palestinian demonstrations that harasse') ON CONFLICT (person_id, criterion_id) DO NOTHING;
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (21, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Sponsored HOPE Act (S7034A) adopting IHRA antisemitism definition, previously urged federal support for Israel as an ally, and endorsed Israel''s defense in 2009 statement.', 'Primary sponsor of S7034A (HOPE Act) requiring state agencies to use IHRA antisemitism definition. In 2009 issued statement urging the federal administration to "continue to support our ally, Israel." Sources: https://www.nysenate.gov/legislation/bills/2025/S7034/amendment/A ; https://www.nysenate.gov/newsroom/in-the-news/2009/kevin-s-parker/statement-state-senator-kevin-parker-violent-attacks') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Sponsored HOPE Act (S7034A) adopting IHRA antisemitism definition, previously urged federal support for Israel as an ally, and endorsed Israel''s defense in 2009 statement.', summary = 'Primary sponsor of S7034A (HOPE Act) requiring state agencies to use IHRA antisemitism definition. In 2009 issued statement urging the federal administration to "continue to support our ally, Israel." Sources: https://www.nysenate.gov/legislation/bills/2025/S7034/amendment/A ; https://www.nysenate.gov/newsroom/in-the-news/2009/kevin-s-parker/statement-state-senator-kevin-parker-violent-attacks', updated_at = NOW();
