INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (22, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'First Sephardic Orthodox Jewish state senator, co-sponsor of HOPE Act (S7034A) adopting IHRA antisemitism definition, represents heavily Jewish Brooklyn district (Borough Park, Midwood), and focuses on religious liberties and Jewish community needs.', 'Won May 2025 special election as first Sephardic Jew elected to state senate. Cosponsor of S7034A (HOPE Act). Co-founder and board chair of Teach NYS advocating for yeshiva funding. Represents Borough Park, Midwood, Flatbush — heavily Jewish neighborhoods. Focus on religious liberties and Jewish community infrastructure. Sources: https://jewishpress.com/indepth/front-page/sam-sutton-quietly-begins-career-in-the-state-senate/2025/06/06/ ; https://tjvnews.com/2025/05/democrat-sam-sutton-clinches-v') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'First Sephardic Orthodox Jewish state senator, co-sponsor of HOPE Act (S7034A) adopting IHRA antisemitism definition, represents heavily Jewish Brooklyn district (Borough Park, Midwood), and focuses on religious liberties and Jewish community needs.', summary = 'Won May 2025 special election as first Sephardic Jew elected to state senate. Cosponsor of S7034A (HOPE Act). Co-founder and board chair of Teach NYS advocating for yeshiva funding. Represents Borough Park, Midwood, Flatbush — heavily Jewish neighborhoods. Focus on religious liberties and Jewish community infrastructure. Sources: https://jewishpress.com/indepth/front-page/sam-sutton-quietly-begins-career-in-the-state-senate/2025/06/06/ ; https://tjvnews.com/2025/05/democrat-sam-sutton-clinches-v', updated_at = NOW();
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (22, 5, 'Won May 2025 special election as first Sephardic Jew elected to state senate. Cosponsor of S7034A (HOPE Act). Co-founder and board chair of Teach NYS advocating for yeshiva funding. Represents Borough') ON CONFLICT (person_id, criterion_id) DO NOTHING;
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (23, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Publicly stressed her "strong backing of Israel," received Distinguished Legislator Award from COJO Flatbush, and strongly condemned Oct 7 attacks as a "travesty."', 'Received Distinguished Legislator Award from COJO Flatbush in 2025, where she "stressed her strong backing of Israel and her commitment to speaking out against anti-Semitism." In Oct 2023 stated: "What is happening in Israel is an absolute travesty... we stand with our Jewish brothers and sisters and denounce the brutality of this terrorist attack." Sources: https://www.nysenate.gov/newsroom/in-the-news/2025/jessica-scarcella-spanton/cojo-flatbush-honors-legislators-israeli ; https://www.nysenat') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Publicly stressed her "strong backing of Israel," received Distinguished Legislator Award from COJO Flatbush, and strongly condemned Oct 7 attacks as a "travesty."', summary = 'Received Distinguished Legislator Award from COJO Flatbush in 2025, where she "stressed her strong backing of Israel and her commitment to speaking out against anti-Semitism." In Oct 2023 stated: "What is happening in Israel is an absolute travesty... we stand with our Jewish brothers and sisters and denounce the brutality of this terrorist attack." Sources: https://www.nysenate.gov/newsroom/in-the-news/2025/jessica-scarcella-spanton/cojo-flatbush-honors-legislators-israeli ; https://www.nysenat', updated_at = NOW();
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (23, 12, 'Received Distinguished Legislator Award from COJO Flatbush in 2025, where she "stressed her strong backing of Israel and her commitment to speaking out against anti-Semitism." In Oct 2023 stated: "Wha') ON CONFLICT (person_id, criterion_id) DO NOTHING;
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (23, 14, 'Received Distinguished Legislator Award from COJO Flatbush in 2025, where she "stressed her strong backing of Israel and her commitment to speaking out against anti-Semitism." In Oct 2023 stated: "Wha') ON CONFLICT (person_id, criterion_id) DO NOTHING;
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (24, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Republican Deputy Minority Leader from Staten Island. Part of Senate Republican Conference that has uniformly supported Israel, though limited individual statements found.', 'Deputy Minority Leader of the Senate Republican Conference, which has taken strong pro-Israel positions including antisemitism working group, hostage rallies, and anti-BDS legislation. No individual Israel-specific statements found beyond conference participation. Source: https://en.wikipedia.org/wiki/Andrew_Lanza') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Republican Deputy Minority Leader from Staten Island. Part of Senate Republican Conference that has uniformly supported Israel, though limited individual statements found.', summary = 'Deputy Minority Leader of the Senate Republican Conference, which has taken strong pro-Israel positions including antisemitism working group, hostage rallies, and anti-BDS legislation. No individual Israel-specific statements found beyond conference participation. Source: https://en.wikipedia.org/wiki/Andrew_Lanza', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (25, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'Primary sponsor of "Not On Our Dime" bill S606, arrested at pro-Palestine protest, used both "genocide" and "apartheid" language regarding Israel, called for immediate ceasefire, and stood in solidarity with pro-Palestinian student encampments.', 'Primary sponsor of S606 "Not On Our Dime" act. Called for ceasefire Oct 16, 2023. Arrested at pro-Palestine rally Oct 20, 2023. Posted: "A genocide is still occurring in Gaza" (April 2024). Posted: "We should not be subsidizing apartheid states... Free Palestine" (June 2020). Stood in solidarity with student encampments "calling for an end to the ongoing genocide in Gaza." Sources: https://www.nysenate.gov/newsroom/press-releases/2024/jabari-brisport/socialists-office-stand-solidarity-student-en') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'Primary sponsor of "Not On Our Dime" bill S606, arrested at pro-Palestine protest, used both "genocide" and "apartheid" language regarding Israel, called for immediate ceasefire, and stood in solidarity with pro-Palestinian student encampments.', summary = 'Primary sponsor of S606 "Not On Our Dime" act. Called for ceasefire Oct 16, 2023. Arrested at pro-Palestine rally Oct 20, 2023. Posted: "A genocide is still occurring in Gaza" (April 2024). Posted: "We should not be subsidizing apartheid states... Free Palestine" (June 2020). Stood in solidarity with student encampments "calling for an end to the ongoing genocide in Gaza." Sources: https://www.nysenate.gov/newsroom/press-releases/2024/jabari-brisport/socialists-office-stand-solidarity-student-en', updated_at = NOW();
