INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (28, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'Jewish senator who strongly condemned Oct 7 and demanded hostage release, but also criticized Netanyahu government''s "mass destruction of Gaza," called for ceasefire through negotiations, and signed open letter from Jewish officials critical of Israeli military conduct.', 'Led November 2023 Jewish elected officials'' statement condemning Oct 7 as "monstrous and indefensible" and demanding hostage release. Co-authored February 2024 open letter stating Israeli government "cannot continue the mass destruction of Gaza and the killing of civilians." On Oct 7 anniversary called on "all parties to take meaningful action to secure a ceasefire agreement." Criticized Netanyahu government but did not support BDS or use "genocide"/"apartheid" language. Sources: https://www.nys') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'Jewish senator who strongly condemned Oct 7 and demanded hostage release, but also criticized Netanyahu government''s "mass destruction of Gaza," called for ceasefire through negotiations, and signed open letter from Jewish officials critical of Israeli military conduct.', summary = 'Led November 2023 Jewish elected officials'' statement condemning Oct 7 as "monstrous and indefensible" and demanding hostage release. Co-authored February 2024 open letter stating Israeli government "cannot continue the mass destruction of Gaza and the killing of civilians." On Oct 7 anniversary called on "all parties to take meaningful action to secure a ceasefire agreement." Criticized Netanyahu government but did not support BDS or use "genocide"/"apartheid" language. Sources: https://www.nys', updated_at = NOW();
