INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (31, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'Co-sponsor of "Not On Our Dime" bill S606, joined JVP protest at Grand Central demanding ceasefire, and was among earliest state senators to publicly call for ceasefire in Gaza.', 'Cosponsor of S606 "Not On Our Dime" act. On Oct 27, 2023, joined Jewish Voice for Peace protest at Grand Central Terminal demanding immediate ceasefire, stating: "I stood in solidarity with the Jewish Voice for Peace-NYC alongside my colleagues... demanding an immediate ceasefire in Gaza to save lives." Sources: https://trackbill.com/bill/new-york-senate-bill-606 ; https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'Co-sponsor of "Not On Our Dime" bill S606, joined JVP protest at Grand Central demanding ceasefire, and was among earliest state senators to publicly call for ceasefire in Gaza.', summary = 'Cosponsor of S606 "Not On Our Dime" act. On Oct 27, 2023, joined Jewish Voice for Peace protest at Grand Central Terminal demanding immediate ceasefire, stating: "I stood in solidarity with the Jewish Voice for Peace-NYC alongside my colleagues... demanding an immediate ceasefire in Gaza to save lives." Sources: https://trackbill.com/bill/new-york-senate-bill-606 ; https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', updated_at = NOW();
