INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (33, (SELECT id FROM topics WHERE slug = 'israel'), 'oppose', 'inferred', 'ai', 'Progressive Bronx Democrat who has been associated with colleagues calling for ceasefire and humanitarian aid to Gaza. Referenced as a collaborator with Senators Salazar and Gonzalez on related legislation.', 'Cited as a "proud colleague" in Senator Gonzalez''s October 2023 ceasefire statement. Worked with Salazar and Gallagher on Gaza-related legislation. Listed among NY elected officials calling for ceasefire in City & State NY tracker (https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'oppose', rationale = 'Progressive Bronx Democrat who has been associated with colleagues calling for ceasefire and humanitarian aid to Gaza. Referenced as a collaborator with Senators Salazar and Gonzalez on related legislation.', summary = 'Cited as a "proud colleague" in Senator Gonzalez''s October 2023 ceasefire statement. Worked with Salazar and Gallagher on Gaza-related legislation. Listed among NY elected officials calling for ceasefire in City & State NY tracker (https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/).', updated_at = NOW();
