INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (35, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'As Senate Majority Leader, attended the "Westchester Stands With Israel" rally on Oct 10, 2023 at Temple Israel of White Plains. Deliberately avoided bringing the Israel-Gaza conflict to the Senate floor, stating the legislature should focus on state-level issues rather than international matters.', 'Spoke at "Westchester Stands With Israel" rally, Oct 10, 2023 (https://www.nysenate.gov/newsroom/articles/2023/shelley-b-mayer/lohud-westchester-stands-israel-during-rally-temple-israel). In Jan 2024, said: "Part of why we don''t deal with international things in this conference is because we could spend a lot of time talking about the ills of the international community" (https://ny1.com/nyc/all-boroughs/politics/2024/03/21/israel-hamas-war-fosters--tension--among-albany-lawmakers).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'As Senate Majority Leader, attended the "Westchester Stands With Israel" rally on Oct 10, 2023 at Temple Israel of White Plains. Deliberately avoided bringing the Israel-Gaza conflict to the Senate floor, stating the legislature should focus on state-level issues rather than international matters.', summary = 'Spoke at "Westchester Stands With Israel" rally, Oct 10, 2023 (https://www.nysenate.gov/newsroom/articles/2023/shelley-b-mayer/lohud-westchester-stands-israel-during-rally-temple-israel). In Jan 2024, said: "Part of why we don''t deal with international things in this conference is because we could spend a lot of time talking about the ills of the international community" (https://ny1.com/nyc/all-boroughs/politics/2024/03/21/israel-hamas-war-fosters--tension--among-albany-lawmakers).', updated_at = NOW();
