INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (37, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Jewish state senator who issued strong pro-Israel statement ("We stand in full support of Israel"), attended Westchester rally for Israel, switched endorsement from Rep. Bowman to Latimer over Bowman''s Israel stance, and has vocally condemned antisemitism.', 'Oct 10, 2023 statement: "We stand in full support of Israel at this moment of peril" (https://www.nysenate.gov/newsroom/articles/2023/shelley-b-mayer/statement-senator-shelley-mayer-war-israel). Attended Westchester Stands With Israel rally at Temple Israel of White Plains. Switched endorsement from Bowman to Latimer, stating "After October 7, it was extremely evident that our congressman had failed" the Jewish community (https://www.cnn.com/2024/05/12/politics/jamaal-bowman-gaza-war-reelection-') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Jewish state senator who issued strong pro-Israel statement ("We stand in full support of Israel"), attended Westchester rally for Israel, switched endorsement from Rep. Bowman to Latimer over Bowman''s Israel stance, and has vocally condemned antisemitism.', summary = 'Oct 10, 2023 statement: "We stand in full support of Israel at this moment of peril" (https://www.nysenate.gov/newsroom/articles/2023/shelley-b-mayer/statement-senator-shelley-mayer-war-israel). Attended Westchester Stands With Israel rally at Temple Israel of White Plains. Switched endorsement from Bowman to Latimer, stating "After October 7, it was extremely evident that our congressman had failed" the Jewish community (https://www.cnn.com/2024/05/12/politics/jamaal-bowman-gaza-war-reelection-', updated_at = NOW();
