INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (38, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Republican member of the Senate Antisemitism Working Group, co-sponsored S531 antisemitism vandalism act, sponsored S7752 Combating Campus Antisemitism Act, and has been vocal about rising antisemitism after Oct 7.', 'Member of Senate Republican Antisemitism Working Group (https://www.nysenate.gov/newsroom/press-releases/2023/bill-weber/senator-bill-weber-appointed-antisemitism-working-group). Co-sponsored S531 antisemitism vandalism act. Sponsored S7752 campus antisemitism bill. Stated "Antisemitism was running unchecked before the October 7th massacre and has only increased since then" (https://www.nysenate.gov/newsroom/press-releases/2024/bill-weber/republican-state-senators-unveil-antisemitism-report). Co') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Republican member of the Senate Antisemitism Working Group, co-sponsored S531 antisemitism vandalism act, sponsored S7752 Combating Campus Antisemitism Act, and has been vocal about rising antisemitism after Oct 7.', summary = 'Member of Senate Republican Antisemitism Working Group (https://www.nysenate.gov/newsroom/press-releases/2023/bill-weber/senator-bill-weber-appointed-antisemitism-working-group). Co-sponsored S531 antisemitism vandalism act. Sponsored S7752 campus antisemitism bill. Stated "Antisemitism was running unchecked before the October 7th massacre and has only increased since then" (https://www.nysenate.gov/newsroom/press-releases/2024/bill-weber/republican-state-senators-unveil-antisemitism-report). Co', updated_at = NOW();
