INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (39, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Republican who co-sponsored S531 antisemitism vandalism act, joined the Senate Antisemitism Working Group, and has focused on combating antisemitism and holding officials accountable for protecting Jewish communities.', 'Joined Senate Republican Antisemitism Working Group in 2026 (https://www.nysenate.gov/newsroom/press-releases/2026/rob-rolison/senator-rob-rolison-joins-anti-semitism-working-group). Co-sponsored S531 antisemitism vandalism act. Told JNS his priority is "holding state officials accountable for what he views as failures to protect public safety" regarding Jewish communities (https://www.jns.org/new-member-of-ny-state-senate-jew-hatred-panel-aims-to-hold-state-officials-accountable-on-safety/).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Republican who co-sponsored S531 antisemitism vandalism act, joined the Senate Antisemitism Working Group, and has focused on combating antisemitism and holding officials accountable for protecting Jewish communities.', summary = 'Joined Senate Republican Antisemitism Working Group in 2026 (https://www.nysenate.gov/newsroom/press-releases/2026/rob-rolison/senator-rob-rolison-joins-anti-semitism-working-group). Co-sponsored S531 antisemitism vandalism act. Told JNS his priority is "holding state officials accountable for what he views as failures to protect public safety" regarding Jewish communities (https://www.jns.org/new-member-of-ny-state-senate-jew-hatred-panel-aims-to-hold-state-officials-accountable-on-safety/).', updated_at = NOW();
