INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (40, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Westchester Democrat who has engaged with the Jewish community, honored residents during Jewish American Heritage Month, and spoken about combating antisemitism, but has not made strong public statements on the Israel-Gaza conflict specifically.', 'Honored residents at Jewish American Heritage Month commemoration, stating "As we face a troubling rise in antisemitism, it''s more important than ever to celebrate those who contribute to the rich, diverse tapestry of our state" (https://www.nysenate.gov/newsroom/press-releases/2025/pete-harckham/harckham-honors-three-sd40-residents-during-jewish). Controversy over honoring a school board member who used "From the River to the Sea" phrase (https://yonkerstimes.com/harckham-honors-school-board-me') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Westchester Democrat who has engaged with the Jewish community, honored residents during Jewish American Heritage Month, and spoken about combating antisemitism, but has not made strong public statements on the Israel-Gaza conflict specifically.', summary = 'Honored residents at Jewish American Heritage Month commemoration, stating "As we face a troubling rise in antisemitism, it''s more important than ever to celebrate those who contribute to the rich, diverse tapestry of our state" (https://www.nysenate.gov/newsroom/press-releases/2025/pete-harckham/harckham-honors-three-sd40-residents-during-jewish). Controversy over honoring a school board member who used "From the River to the Sea" phrase (https://yonkerstimes.com/harckham-honors-school-board-me', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (42, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'Has not taken a strong public position on Israel-Gaza. As Investigations Committee chair, was involved in discussions about campus antisemitism at Columbia but has framed the issue in terms of party unity. Had a 2022 controversy involving statements blamed on the "unvaccinated" Jewish community.', 'Discussed Israel-Gaza as DNC chair candidate, saying "The conflict in Gaza is the perfect example as to how we''ve gotten to this point, where we frayed on both edges of the once large Democratic tent." As Investigations Committee chair, was called on by Republicans to hold hearings on Columbia campus protests. Had 2022 controversy blaming "unvaccinated" Jewish community for polio case (https://www.nrcc.org/2022/07/22/will-pat-ryan-renounce-skoufis-endorsement-after-antisemitic-remarks/).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'Has not taken a strong public position on Israel-Gaza. As Investigations Committee chair, was involved in discussions about campus antisemitism at Columbia but has framed the issue in terms of party unity. Had a 2022 controversy involving statements blamed on the "unvaccinated" Jewish community.', summary = 'Discussed Israel-Gaza as DNC chair candidate, saying "The conflict in Gaza is the perfect example as to how we''ve gotten to this point, where we frayed on both edges of the once large Democratic tent." As Investigations Committee chair, was called on by Republicans to hold hearings on Columbia campus protests. Had 2022 controversy blaming "unvaccinated" Jewish community for polio case (https://www.nrcc.org/2022/07/22/will-pat-ryan-renounce-skoufis-endorsement-after-antisemitic-remarks/).', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (43, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Republican and military veteran who posted on Facebook asking constituents to "pray for Israel" after the Oct 7 attacks. No detailed policy positions found but general solidarity expressed.', 'Facebook post from campaign account asking constituents to "please join me in praying for Israel" (https://www.facebook.com/JakeAshbyforNYSSenate/posts/please-join-me-in-praying-for-israel-please-pray-for-a-people-of-faith-a-people-/962654662340037/).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Republican and military veteran who posted on Facebook asking constituents to "pray for Israel" after the Oct 7 attacks. No detailed policy positions found but general solidarity expressed.', summary = 'Facebook post from campaign account asking constituents to "please join me in praying for Israel" (https://www.facebook.com/JakeAshbyforNYSSenate/posts/please-join-me-in-praying-for-israel-please-pray-for-a-people-of-faith-a-people-/962654662340037/).', updated_at = NOW();
