INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (44, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Sponsored multiple antisemitism bills in direct response to Oct 7, including legislation to elevate cemetery desecration to hate crime felony and to expel students from SUNY/CUNY for antisemitic hate crimes. Explicitly referenced Hamas terrorist attack as motivating his legislative push.', 'Sponsored bipartisan cemetery desecration bill elevating antisemitic cemetery desecration to class D/C felony (https://www.nysenate.gov/newsroom/press-releases/2024/james-tedisco/tedisco-eichenstein-call-new-bipartisan-bill-add). Sponsored campus antisemitism bill adding expulsion penalty (https://www.nysenate.gov/newsroom/press-releases/2023/james-tedisco/tedisco-no-tax-dollars-anti-semites-racists-college). Explicitly cited "rising incidents of antisemitism...following the October 7th Hamas te') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Sponsored multiple antisemitism bills in direct response to Oct 7, including legislation to elevate cemetery desecration to hate crime felony and to expel students from SUNY/CUNY for antisemitic hate crimes. Explicitly referenced Hamas terrorist attack as motivating his legislative push.', summary = 'Sponsored bipartisan cemetery desecration bill elevating antisemitic cemetery desecration to class D/C felony (https://www.nysenate.gov/newsroom/press-releases/2024/james-tedisco/tedisco-eichenstein-call-new-bipartisan-bill-add). Sponsored campus antisemitism bill adding expulsion penalty (https://www.nysenate.gov/newsroom/press-releases/2023/james-tedisco/tedisco-no-tax-dollars-anti-semites-racists-college). Explicitly cited "rising incidents of antisemitism...following the October 7th Hamas te', updated_at = NOW();
