INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (46, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'Called for ceasefire and return of hostages but also condemned antisemitism and was challenged for not co-signing a Republican antisemitism bill. Introduced Holocaust Memorial legislation. Nuanced position balancing criticism of Netanyahu government with opposing antisemitism.', 'Jan 24, 2024 Instagram post: "We need a ceasefire now and the return of all hostages." Condemned increases in hate speech post-Oct 7, said "One can oppose or criticize the policies of Netanyahu''s government and not be antisemitic." Challenged by Republican opponent for not co-signing GOP antisemitism tuition bill (https://www.dailygazette.com/news/govt_politics/danz-fahy-antisemitism/article_94c3fe42-1137-11ef-a445-e7f56fb965e2.html). Introduced and passed NYS Holocaust Memorial legislation for') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'Called for ceasefire and return of hostages but also condemned antisemitism and was challenged for not co-signing a Republican antisemitism bill. Introduced Holocaust Memorial legislation. Nuanced position balancing criticism of Netanyahu government with opposing antisemitism.', summary = 'Jan 24, 2024 Instagram post: "We need a ceasefire now and the return of all hostages." Condemned increases in hate speech post-Oct 7, said "One can oppose or criticize the policies of Netanyahu''s government and not be antisemitic." Challenged by Republican opponent for not co-signing GOP antisemitism tuition bill (https://www.dailygazette.com/news/govt_politics/danz-fahy-antisemitism/article_94c3fe42-1137-11ef-a445-e7f56fb965e2.html). Introduced and passed NYS Holocaust Memorial legislation for', updated_at = NOW();
