INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (47, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'As NYC Council member, "unequivocally condemned the violence" of Oct 7 and pledged to "stand with Israel." Questioned CUNY chancellor on antisemitism. Endorsed by pro-Israel Zioness Action Fund which praised him for "always standing with the Jewish community and the people of Israel."', 'Oct 7, 2023: "unequivocally condemn[ed] the violence" and pledged to "stand with Israel." Attended dedication of ''Yad Vashem Way'' in Midtown Manhattan. Questioned CUNY Chancellor on combating antisemitism (https://citymeetings.nyc). Endorsed by Zioness Action Fund: "Erik has always stood with the Jewish community and the people of Israel and condemned antisemitism" (https://zionessaction.org/2025-nyc-democratic-primary-endorsements/).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'As NYC Council member, "unequivocally condemned the violence" of Oct 7 and pledged to "stand with Israel." Questioned CUNY chancellor on antisemitism. Endorsed by pro-Israel Zioness Action Fund which praised him for "always standing with the Jewish community and the people of Israel."', summary = 'Oct 7, 2023: "unequivocally condemn[ed] the violence" and pledged to "stand with Israel." Attended dedication of ''Yad Vashem Way'' in Midtown Manhattan. Questioned CUNY Chancellor on combating antisemitism (https://citymeetings.nyc). Endorsed by Zioness Action Fund: "Erik has always stood with the Jewish community and the people of Israel and condemned antisemitism" (https://zionessaction.org/2025-nyc-democratic-primary-endorsements/).', updated_at = NOW();
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (47, 12, 'Oct 7, 2023: "unequivocally condemn[ed] the violence" and pledged to "stand with Israel." Attended dedication of ''Yad Vashem Way'' in Midtown Manhattan. Questioned CUNY Chancellor on combating antisemi') ON CONFLICT (person_id, criterion_id) DO NOTHING;
