INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (51, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Republican member of the Senate Antisemitism Working Group, co-sponsored S531 antisemitism vandalism act, sponsored S8774 expanding prohibition of Nazi symbol harassment. Called for antisemitism legislation to be a priority in Albany. Represents district with a large Jewish community.', 'Member of Senate Republican Antisemitism Working Group (https://www.nysenate.gov/newsroom/press-releases/2024/peter-oberacker/senator-oberacker-calls-antisemitism-legislation-be). Co-sponsored S531 antisemitism vandalism act. Sponsored S8774 expanding Nazi symbol harassment prohibition. Co-authored 2023-2024 antisemitism report with legislative recommendations (https://www.nysenate.gov/newsroom/articles/2024/jack-m-martins/antisemitism-working-group-2023-2024-report).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Republican member of the Senate Antisemitism Working Group, co-sponsored S531 antisemitism vandalism act, sponsored S8774 expanding prohibition of Nazi symbol harassment. Called for antisemitism legislation to be a priority in Albany. Represents district with a large Jewish community.', summary = 'Member of Senate Republican Antisemitism Working Group (https://www.nysenate.gov/newsroom/press-releases/2024/peter-oberacker/senator-oberacker-calls-antisemitism-legislation-be). Co-sponsored S531 antisemitism vandalism act. Sponsored S8774 expanding Nazi symbol harassment prohibition. Co-authored 2023-2024 antisemitism report with legislative recommendations (https://www.nysenate.gov/newsroom/articles/2024/jack-m-martins/antisemitism-working-group-2023-2024-report).', updated_at = NOW();
