INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (53, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Republican member of the Senate Antisemitism Working Group, co-sponsored S531 antisemitism vandalism act, issued statement condemning murders of Israeli Embassy staff members in 2025. Long track record of antisemitism protection legislation.', 'Member of Senate Republican Antisemitism Working Group. Co-sponsored S531 antisemitism vandalism act. Statement condemning murders of Israeli Embassy staff in May 2025 (https://www.nysenate.gov/newsroom/press-releases/2025/joseph-griffo/griffo-statement-murders-israeli-embassy-staff-members). Previously sponsored legislation offering protections against antisemitic acts (https://www.nysenate.gov/newsroom/press-releases/2021/joseph-griffo/griffo-legislation-would-offer-additional-protections).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Republican member of the Senate Antisemitism Working Group, co-sponsored S531 antisemitism vandalism act, issued statement condemning murders of Israeli Embassy staff members in 2025. Long track record of antisemitism protection legislation.', summary = 'Member of Senate Republican Antisemitism Working Group. Co-sponsored S531 antisemitism vandalism act. Statement condemning murders of Israeli Embassy staff in May 2025 (https://www.nysenate.gov/newsroom/press-releases/2025/joseph-griffo/griffo-statement-murders-israeli-embassy-staff-members). Previously sponsored legislation offering protections against antisemitic acts (https://www.nysenate.gov/newsroom/press-releases/2021/joseph-griffo/griffo-legislation-would-offer-additional-protections).', updated_at = NOW();
