INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (54, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Republican who joined the Senate Republican antisemitism working group''s 2024 report release and supported legislative recommendations to combat antisemitism. No specific Israel policy statements found but aligned with pro-Israel Republican caucus positions.', 'Joined antisemitism working group report release March 27, 2024, and supported letter to Governor Hochul recommending legislative action to combat antisemitic hate crimes (https://www.nysenate.gov/newsroom/articles/2024/pamela-helming/senate-republicans-recommend-legislative-action-combat).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Republican who joined the Senate Republican antisemitism working group''s 2024 report release and supported legislative recommendations to combat antisemitism. No specific Israel policy statements found but aligned with pro-Israel Republican caucus positions.', summary = 'Joined antisemitism working group report release March 27, 2024, and supported letter to Governor Hochul recommending legislative action to combat antisemitic hate crimes (https://www.nysenate.gov/newsroom/articles/2024/pamela-helming/senate-republicans-recommend-legislative-action-combat).', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (55, (SELECT id FROM topics WHERE slug = 'israel'), 'oppose', 'inferred', 'ai', 'Called for an immediate ceasefire in Gaza in March 2024, emphasizing humanitarian crisis. Framed her position around protecting civilian lives, women and children, but did not use "genocide" or "apartheid" language.', 'March 28, 2024 statement: "Now, as 1.1 million people -- most of them women and children -- are on the brink of famine, we cannot delay calls for an immediate ceasefire and humanitarian aid to those suffering...we must have the moral courage to protect human life" (https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'oppose', rationale = 'Called for an immediate ceasefire in Gaza in March 2024, emphasizing humanitarian crisis. Framed her position around protecting civilian lives, women and children, but did not use "genocide" or "apartheid" language.', summary = 'March 28, 2024 statement: "Now, as 1.1 million people -- most of them women and children -- are on the brink of famine, we cannot delay calls for an immediate ceasefire and humanitarian aid to those suffering...we must have the moral courage to protect human life" (https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/).', updated_at = NOW();
