INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (59, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_oppose', 'inferred', 'ai', 'DSA-backed senator who called Israeli actions "genocidal," called for unconditional ceasefire on Oct 13, 2023, and co-sponsored S606 "Not On Our Dime" anti-settlement bill. One of the most vocal critics of Israel''s military operations in the NY State Senate.', 'Oct 13, 2023 statement: "Make no mistake, these actions by the Israeli government are genocidal" (https://www.nysenate.gov/newsroom/press-releases/2023/kristen-gonzalez/senator-kristen-gonzalez-responds-ongoing-violence). Oct 27, 2023 detailed statement condemned "the genocidal actions of the IDF" and called "collective punishment" a war crime (https://www.nysenate.gov/newsroom/press-releases/2023/kristen-gonzalez/statement-senator-kristen-gonzalez-responds). Co-sponsored S606 "Not On Our Dime"') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_oppose', rationale = 'DSA-backed senator who called Israeli actions "genocidal," called for unconditional ceasefire on Oct 13, 2023, and co-sponsored S606 "Not On Our Dime" anti-settlement bill. One of the most vocal critics of Israel''s military operations in the NY State Senate.', summary = 'Oct 13, 2023 statement: "Make no mistake, these actions by the Israeli government are genocidal" (https://www.nysenate.gov/newsroom/press-releases/2023/kristen-gonzalez/senator-kristen-gonzalez-responds-ongoing-violence). Oct 27, 2023 detailed statement condemned "the genocidal actions of the IDF" and called "collective punishment" a war crime (https://www.nysenate.gov/newsroom/press-releases/2023/kristen-gonzalez/statement-senator-kristen-gonzalez-responds). Co-sponsored S606 "Not On Our Dime"', updated_at = NOW();
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (59, 3, 'Oct 13, 2023 statement: "Make no mistake, these actions by the Israeli government are genocidal" (https://www.nysenate.gov/newsroom/press-releases/2023/kristen-gonzalez/senator-kristen-gonzalez-respon') ON CONFLICT (person_id, criterion_id) DO NOTHING;
