INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (62, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Senate Republican Leader who created the Antisemitism Working Group in Feb 2023, led the conference''s antisemitism report and legislative package, and co-authored letter urging Governor Hochul to help New Yorkers stranded in Israel after Oct 7.', 'Created Senate Republican Antisemitism Working Group in Feb 2023 (https://www.nysenate.gov/newsroom/press-releases/2023/robert-g-ortt/senate-republican-leader-rob-ortt-announces-creation). Led letter to Governor Hochul to help New Yorkers stranded in Israel (https://www.nysenate.gov/newsroom/press-releases/2025/patricia-canzoneri-fitzpatrick/senator-canzoneri-fitzpatrick-minority). Unveiled antisemitism report with comprehensive legislative recommendations (https://www.nysenate.gov/newsroom/pres') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Senate Republican Leader who created the Antisemitism Working Group in Feb 2023, led the conference''s antisemitism report and legislative package, and co-authored letter urging Governor Hochul to help New Yorkers stranded in Israel after Oct 7.', summary = 'Created Senate Republican Antisemitism Working Group in Feb 2023 (https://www.nysenate.gov/newsroom/press-releases/2023/robert-g-ortt/senate-republican-leader-rob-ortt-announces-creation). Led letter to Governor Hochul to help New Yorkers stranded in Israel (https://www.nysenate.gov/newsroom/press-releases/2025/patricia-canzoneri-fitzpatrick/senator-canzoneri-fitzpatrick-minority). Unveiled antisemitism report with comprehensive legislative recommendations (https://www.nysenate.gov/newsroom/pres', updated_at = NOW();
