INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (130, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Rosenthal led the pushback against the "Not on Our Dime" anti-settlement bill, co-organizing a letter signed by 66 Democratic Assembly members denouncing it as targeting Jewish charities. She also supported buffer zone legislation to protect Jewish institutions from protest harassment.', 'Co-organized letter with 66 Assembly Democrats condemning the "Not on Our Dime" bill as "a ploy to demonize Jewish charities with connections to Israel" (https://www.queensjewishlink.com/index.php/local/79-community-corner/shabsie-saphirstein/8639-rosenthal-and-rozic-lead-pushback-against-leftist-bill-targeting-jewish-orgs). Supported buffer zone legislation at NYC Council hearing (https://www.jta.org/2026/02/26/ny/pro-israel-and-anti-zionist-jews-clash-at-nyc-council-hearing-on-protest-buffer-z') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Rosenthal led the pushback against the "Not on Our Dime" anti-settlement bill, co-organizing a letter signed by 66 Democratic Assembly members denouncing it as targeting Jewish charities. She also supported buffer zone legislation to protect Jewish institutions from protest harassment.', summary = 'Co-organized letter with 66 Assembly Democrats condemning the "Not on Our Dime" bill as "a ploy to demonize Jewish charities with connections to Israel" (https://www.queensjewishlink.com/index.php/local/79-community-corner/shabsie-saphirstein/8639-rosenthal-and-rozic-lead-pushback-against-leftist-bill-targeting-jewish-orgs). Supported buffer zone legislation at NYC Council hearing (https://www.jta.org/2026/02/26/ny/pro-israel-and-anti-zionist-jews-clash-at-nyc-council-hearing-on-protest-buffer-z', updated_at = NOW();
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (130, 16, 'Co-organized letter with 66 Assembly Democrats condemning the "Not on Our Dime" bill as "a ploy to demonize Jewish charities with connections to Israel" (https://www.queensjewishlink.com/index.php/loc') ON CONFLICT (person_id, criterion_id) DO NOTHING;
