INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (132, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Lasher has taken a mainstream pro-Israel Democratic stance, refusing to support arms cutoffs to Israel or call the Gaza war a "genocide." He was endorsed by the pro-Israel Solidarity PAC and has described himself as both "a proud progressive and a proud Zionist."', 'Refused to support anti-Israel aid legislation or call Israel''s actions "genocide" (https://www.algemeiner.com/2026/01/26/ny-democratic-congressional-favorite-refuses-support-anti-israel-aid-legislation-accuse-israel-genocide/). Endorsed by Solidarity PAC (https://nysfocus.com/2024/03/26/israel-pac-new-york-election-democrats). Described campaign as place where one could be "both a proud progressive and a proud Zionist" (https://forward.com/news/766762/micah-lasher-jerry-nadler-congress/).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Lasher has taken a mainstream pro-Israel Democratic stance, refusing to support arms cutoffs to Israel or call the Gaza war a "genocide." He was endorsed by the pro-Israel Solidarity PAC and has described himself as both "a proud progressive and a proud Zionist."', summary = 'Refused to support anti-Israel aid legislation or call Israel''s actions "genocide" (https://www.algemeiner.com/2026/01/26/ny-democratic-congressional-favorite-refuses-support-anti-israel-aid-legislation-accuse-israel-genocide/). Endorsed by Solidarity PAC (https://nysfocus.com/2024/03/26/israel-pac-new-york-election-democrats). Described campaign as place where one could be "both a proud progressive and a proud Zionist" (https://forward.com/news/766762/micah-lasher-jerry-nadler-congress/).', updated_at = NOW();
INSERT INTO person_criteria (person_id, criterion_id, evidence) VALUES (132, 12, 'Refused to support anti-Israel aid legislation or call Israel''s actions "genocide" (https://www.algemeiner.com/2026/01/26/ny-democratic-congressional-favorite-refuses-support-anti-israel-aid-legislati') ON CONFLICT (person_id, criterion_id) DO NOTHING;
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (133, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Wright was endorsed by the pro-Israel Solidarity PAC as part of their inaugural class of candidates. While deferring to foreign affairs experts on aid conditions, he received significant pro-Israel PAC funding.', 'Endorsed by Solidarity PAC, which backs candidates who "value the American alliance with Israel" (https://www.nysolidaritypac.org/jordan-wright). On US aid to Israel, stated he would defer to "foreign affairs experts and officials" (https://jimowles.org/news/candidate-answers-to-joldc-jordan-jg-wright-for-ny-assembly-district-70-2024).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Wright was endorsed by the pro-Israel Solidarity PAC as part of their inaugural class of candidates. While deferring to foreign affairs experts on aid conditions, he received significant pro-Israel PAC funding.', summary = 'Endorsed by Solidarity PAC, which backs candidates who "value the American alliance with Israel" (https://www.nysolidaritypac.org/jordan-wright). On US aid to Israel, stated he would defer to "foreign affairs experts and officials" (https://jimowles.org/news/candidate-answers-to-joldc-jordan-jg-wright-for-ny-assembly-district-70-2024).', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (135, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'De Los Santos was initially a cosponsor of the "Not on Our Dime" anti-settlement bill but reversed course, withdrew his name, and signed the letter condemning it as targeting Jewish charities. This reversal indicates he moved to a pro-Israel position.', 'Withdrew as cosponsor of "Not on Our Dime" bill and signed letter opposing it (https://forward.com/fast-forward/547366/ny-lawmakers-criticize-bill-that-would-penalize-charitable-groups-supporting-israeli-settlements/).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'De Los Santos was initially a cosponsor of the "Not on Our Dime" anti-settlement bill but reversed course, withdrew his name, and signed the letter condemning it as targeting Jewish charities. This reversal indicates he moved to a pro-Israel position.', summary = 'Withdrew as cosponsor of "Not on Our Dime" bill and signed letter opposing it (https://forward.com/fast-forward/547366/ny-lawmakers-criticize-bill-that-would-penalize-charitable-groups-supporting-israeli-settlements/).', updated_at = NOW();
