INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (136, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Bores opposes an arms embargo on Israel, opposed the "Not on Our Dime" bill, and supports a conditional ceasefire (requiring hostage return). He has been characterized as "Progressive Except for Palestine."', 'Opposes arms embargo on Israel, described as non-negotiable for him (https://x.com/petersterne/status/2014002728930848811). Opposed "Not on our dime" bill (https://jewishcurrents.org/why-are-progressive-legislators-opposing-new-yorks-first-anti-settlement-bill). Supports conditional ceasefire requiring hostage return and assurances against future attacks.') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Bores opposes an arms embargo on Israel, opposed the "Not on Our Dime" bill, and supports a conditional ceasefire (requiring hostage return). He has been characterized as "Progressive Except for Palestine."', summary = 'Opposes arms embargo on Israel, described as non-negotiable for him (https://x.com/petersterne/status/2014002728930848811). Opposed "Not on our dime" bill (https://jewishcurrents.org/why-are-progressive-legislators-opposing-new-yorks-first-anti-settlement-bill). Supports conditional ceasefire requiring hostage return and assurances against future attacks.', updated_at = NOW();
