INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (139, (SELECT id FROM topics WHERE slug = 'israel'), 'support', 'inferred', 'ai', 'Seawright has hosted town halls on combating antisemitism, is a member of the Assembly''s Jewish caucus, and has advocated for both Israeli security and Palestinian rights while supporting legislation to combat antisemitism.', 'Hosted antisemitism town hall focused on rise in incidents since Oct. 7 (https://article.wn.com/view/2025/07/30/Upper_East_Side_antisemitism_town_hall_zeroes_in_on_antiIsra_o/). Member of Assembly Jewish caucus (https://rebeccaseawright.com/). Supports post-war plan enfranchising Palestinians while providing safety for Israel.') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'support', rationale = 'Seawright has hosted town halls on combating antisemitism, is a member of the Assembly''s Jewish caucus, and has advocated for both Israeli security and Palestinian rights while supporting legislation to combat antisemitism.', summary = 'Hosted antisemitism town hall focused on rise in incidents since Oct. 7 (https://article.wn.com/view/2025/07/30/Upper_East_Side_antisemitism_town_hall_zeroes_in_on_antiIsra_o/). Member of Assembly Jewish caucus (https://rebeccaseawright.com/). Supports post-war plan enfranchising Palestinians while providing safety for Israel.', updated_at = NOW();
