INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (144, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Dinowitz is one of the most outspoken pro-Israel members of the Assembly, strongly supporting Israel''s right to defend itself "without regard to proportionality," denouncing BDS as antisemitic, and supporting buffer zone legislation around Jewish institutions.', 'Stated "Israel not only has a right to defend itself but must respond in the most substantial possible way against these barbaric attacks without regard to proportionality" (https://www.norwoodnews.org/update-dinowitz-hochul-others-denounce-rally-in-support-of-palestinians-following-terrorist-attack-on-israel/). Called BDS "more about anti-Semitism and destroying the state of Israel" (https://nyassembly.gov/mem/Jeffrey-Dinowitz/story/93885). Supported buffer zone legislation (https://www.jta.org') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Dinowitz is one of the most outspoken pro-Israel members of the Assembly, strongly supporting Israel''s right to defend itself "without regard to proportionality," denouncing BDS as antisemitic, and supporting buffer zone legislation around Jewish institutions.', summary = 'Stated "Israel not only has a right to defend itself but must respond in the most substantial possible way against these barbaric attacks without regard to proportionality" (https://www.norwoodnews.org/update-dinowitz-hochul-others-denounce-rally-in-support-of-palestinians-following-terrorist-attack-on-israel/). Called BDS "more about anti-Semitism and destroying the state of Israel" (https://nyassembly.gov/mem/Jeffrey-Dinowitz/story/93885). Supported buffer zone legislation (https://www.jta.org', updated_at = NOW();
