INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (146, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'As Assembly Speaker, Heastie blocked a bipartisan bill commemorating Oct. 7 from reaching the floor, but also initially expressed concerns about Mamdani''s pro-Palestinian views before eventually endorsing him for mayor. His approach has been cautious and politically calculated rather than ideologically driven.', 'Blocked bipartisan bill commemorating Oct. 7 attack (https://www.aol.com/news/andrew-cuomo-refuses-condemn-assembly-195117828.html). Later endorsed Mamdani for NYC mayor despite pro-Palestinian views (https://www.cbsnews.com/newyork/news/zohran-mamdani-carl-heastie-endorsement-nyc-mayor-election/).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'As Assembly Speaker, Heastie blocked a bipartisan bill commemorating Oct. 7 from reaching the floor, but also initially expressed concerns about Mamdani''s pro-Palestinian views before eventually endorsing him for mayor. His approach has been cautious and politically calculated rather than ideologically driven.', summary = 'Blocked bipartisan bill commemorating Oct. 7 attack (https://www.aol.com/news/andrew-cuomo-refuses-condemn-assembly-195117828.html). Later endorsed Mamdani for NYC mayor despite pro-Palestinian views (https://www.cbsnews.com/newyork/news/zohran-mamdani-carl-heastie-endorsement-nyc-mayor-election/).', updated_at = NOW();
INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (147, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Septimo has strongly defended Israel''s right to self-defense, opposed the "Not on Our Dime" bill as a "disturbing effort to delegitimize Israel," visited Israel on an AIPAC-affiliated trip, and has repeatedly met with pro-Israel advocates.', 'Stated she would "continue to stand by [Israel''s] right to defend itself" (https://jewishinsider.com/2025/12/amanda-septimo-ritchie-torres-primary-zohran-mamdani-ally/). Called "Not on Our Dime" a "disturbing effort to bring the delegitimization of Israel to the halls of power" (same source). Visited Israel in 2016 on AIPAC-affiliated trip; attended AIPAC events as recently as late 2023.') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Septimo has strongly defended Israel''s right to self-defense, opposed the "Not on Our Dime" bill as a "disturbing effort to delegitimize Israel," visited Israel on an AIPAC-affiliated trip, and has repeatedly met with pro-Israel advocates.', summary = 'Stated she would "continue to stand by [Israel''s] right to defend itself" (https://jewishinsider.com/2025/12/amanda-septimo-ritchie-torres-primary-zohran-mamdani-ally/). Called "Not on Our Dime" a "disturbing effort to bring the delegitimization of Israel to the halls of power" (same source). Visited Israel in 2016 on AIPAC-affiliated trip; attended AIPAC events as recently as late 2023.', updated_at = NOW();
