INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (151, (SELECT id FROM topics WHERE slug = 'israel'), 'strongly_support', 'inferred', 'ai', 'Paulin is one of the most vocal pro-Israel members of the Assembly, with family in Israel. She "stands firmly behind Israel" and has called for America to "stand unequivocally with Israel." She is a member of the National Association of Jewish Legislators.', '"Stands firmly behind Israel and feels strongly that Israel must defend itself and prevail" with family living in Israel (https://assembly.state.ny.us/mem/Amy-Paulin/story/107680). Statement on Iran''s attack: "I stand with Israel and pray that America continues to stand unequivocally with Israel" (https://yonkerstimes.com/assemblywoman-amy-paulins-statement-regarding-irans-attack-on-israel/).') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'strongly_support', rationale = 'Paulin is one of the most vocal pro-Israel members of the Assembly, with family in Israel. She "stands firmly behind Israel" and has called for America to "stand unequivocally with Israel." She is a member of the National Association of Jewish Legislators.', summary = '"Stands firmly behind Israel and feels strongly that Israel must defend itself and prevail" with family living in Israel (https://assembly.state.ny.us/mem/Amy-Paulin/story/107680). Statement on Iran''s attack: "I stand with Israel and pray that America continues to stand unequivocally with Israel" (https://yonkerstimes.com/assemblywoman-amy-paulins-statement-regarding-irans-attack-on-israel/).', updated_at = NOW();
