INSERT INTO positions (person_id, topic_id, stance, confidence, assessment_type, rationale, summary) VALUES (153, (SELECT id FROM topics WHERE slug = 'israel'), 'neutral', 'inferred', 'ai', 'Sayegh, a Jordanian-American, issued statements on the Israel-Palestine crisis in both 2021 and 2023 but the specific content could not be confirmed. His Arab-American heritage and balanced public posture suggest a nuanced position, but insufficient detail is available.', 'Published statement on "Ongoing Crisis in Israel and Palestine" on Oct. 17, 2023 (https://yonkerstimes.com/assemblyman-nader-sayegh-comments-on-the-ongoing-crisis-in-israel-and-palestine/). Content of statement not accessible via search results.') ON CONFLICT (person_id, topic_id, assessment_type) DO UPDATE SET stance = 'neutral', rationale = 'Sayegh, a Jordanian-American, issued statements on the Israel-Palestine crisis in both 2021 and 2023 but the specific content could not be confirmed. His Arab-American heritage and balanced public posture suggest a nuanced position, but insufficient detail is available.', summary = 'Published statement on "Ongoing Crisis in Israel and Palestine" on Oct. 17, 2023 (https://yonkerstimes.com/assemblyman-nader-sayegh-comments-on-the-ongoing-crisis-in-israel-and-palestine/). Content of statement not accessible via search results.', updated_at = NOW();
